INSERT INTO public.brazil_diary_posts (entry_id, title, url, posted_at, category, body_text, body_clean, importance_score, source)
VALUES
(1, 'すばらしい祝福とともに', 'https://tlccc-mission-bra.blogspot.com/2011/08/blog-post.html', '2011-08-21', 'ブラジル日記', 'こんばんは、エパタです。いつも懇意にしてくださり、日曜日ごとにごちそうしてくださっている方に「天国はあるんです」という話からイエス様の身代わりの十字架について、お話するチャンスがありました。ご本人は敬虔な仏教徒であられますが、「イエス様を信じますか」と聞いたら、「信じるよ」と言われたので、「今受け入れましょう」と言ったところ、「もっとよく考えてから」とのことでした。受け入れることができますように。。。聖霊様が働いておられるのを感じました。主にすべてのご栄光をお返しします。', 'こんばんは、エパタです。いつも懇意にしてくださり、日曜日ごとにごちそうしてくださっている方に「天国はあるんです」という話からイエス様の身代わりの十字架について、お話するチャンスがありました。ご本人は敬虔な仏教徒であられますが、「イエス様を信じますか」と聞いたら、「信じるよ」と言われたので、「今受け入れましょう」と言ったところ、「もっとよく考えてから」とのことでした。受け入れることができますように。。。聖霊様が働いておられるのを感じました。主にすべてのご栄光をお返しします。', 'C', 'brazil_diary_blogger'),
(2, '他教会で賛美♪', 'https://tlccc-mission-bra.blogspot.com/2011/08/blog-post_28.html', '2011-08-28', 'ブラジル日記', '路上での賛美を通して、若いクリスチャン女性との関わりが開かれ、その方の教会の夜の礼拝に行っていますが、この前の日曜日は、また別の教会に行く機会がありました。<br />礼拝の中で、牧師が、「何か話したり歌ったりする方はいませんか」と呼びかけられたので、やすらぎの歌10集61番を日本語と英語で賛美しました。最初にポルトガル語で歌詞の意味を説明すると、「アーメン！」「ハレルヤ！」と声が上がり、歌集を持って行っていなかったので伴奏がつけられず、一人でアカペラで賛美しましたが、手拍子がわき起こり、とても祝福された時となりました。<br />主の導きに感謝します♪ (B)', '路上での賛美を通して、若いクリスチャン女性との関わりが開かれ、その方の教会の夜の礼拝に行っていますが、この前の日曜日は、また別の教会に行く機会がありました。
礼拝の中で、牧師が、「何か話したり歌ったりする方はいませんか」と呼びかけられたので、やすらぎの歌10集61番を日本語と英語で賛美しました。最初にポルトガル語で歌詞の意味を説明すると、「アーメン！」「ハレルヤ！」と声が上がり、歌集を持って行っていなかったので伴奏がつけられず、一人でアカペラで賛美しましたが、手拍子がわき起こり、とても祝福された時となりました。
主の導きに感謝します♪ (B)', 'C', 'brazil_diary_blogger'),
(3, 'トラクトをあげました', 'https://tlccc-mission-bra.blogspot.com/2011/08/blog-post_30.html', '2011-08-30', 'ブラジル日記', 'こんばんは、エパタです。<br />ショッピングセンターの「Lojas Americanas」というお店のレジに並んでいたら、日系人のお父さんと娘さん（５歳くらい？）の親子が後ろに並んでいました。そこで、さっそく今日届いた漫画トラクトを差し上げることができました。日本へも働きに行かれたことがあるそうです。主よ、どうぞ用いてください。<br />', 'こんばんは、エパタです。
ショッピングセンターの「Lojas Americanas」というお店のレジに並んでいたら、日系人のお父さんと娘さん（５歳くらい？）の親子が後ろに並んでいました。そこで、さっそく今日届いた漫画トラクトを差し上げることができました。日本へも働きに行かれたことがあるそうです。主よ、どうぞ用いてください。', 'C', 'brazil_diary_blogger'),
(4, '日本から送ってもらったトラクト', NULL, '2011-08-30', 'ブラジル日記', NULL, NULL, 'C', 'brazil_diary_blogger'),
(5, '行ってきました！', 'https://tlccc-mission-bra.blogspot.com/2011/08/blog-post_31.html', '2011-08-31', 'ブラジル日記', 'トラクトを日系の方を中心に、日本語を勉強したいブラジル人にも配ってきました。とても立派なトラクトなので、買ってもいいという感じの方もおられ、「いくら？」と聞かれました。思わず値段をつけてしまいたくなりましたが、飲み込み、「ただです！」と言うと、本当に有難いという感じで受け取ってくださいました。用いてください。また、さらに御心の方に手渡されますように。。。', 'トラクトを日系の方を中心に、日本語を勉強したいブラジル人にも配ってきました。とても立派なトラクトなので、買ってもいいという感じの方もおられ、「いくら？」と聞かれました。思わず値段をつけてしまいたくなりましたが、飲み込み、「ただです！」と言うと、本当に有難いという感じで受け取ってくださいました。用いてください。また、さらに御心の方に手渡されますように。。。', 'C', 'brazil_diary_blogger'),
(6, 'いやしのためにお祈りください', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post.html', '2011-09-01', 'ブラジル日記', 'こんばんは、エパタです。以前グァララペスに住んでいた時に、リューマチのいやしの祈りのために訪問していたRさんに、久しぶりに電話して近況を聞きました。すると、右目が原因不明で視力が落ち、ほとんど見えない状態だそうです。南米最高の技術を持つと言われるSJRP市の病院に通っていますが、薬が非常に強い薬らしく不眠で、右耳もほとんど聞こえなくなってきているそうです。手術の予定だったそうですが、医師より「原因がはっきりせず、危険を伴う個所なので、様子を見ている」そうです。原因がはっきりし、いやされますように、お祈りください。', 'こんばんは、エパタです。以前グァララペスに住んでいた時に、リューマチのいやしの祈りのために訪問していたRさんに、久しぶりに電話して近況を聞きました。すると、右目が原因不明で視力が落ち、ほとんど見えない状態だそうです。南米最高の技術を持つと言われるSJRP市の病院に通っていますが、薬が非常に強い薬らしく不眠で、右耳もほとんど聞こえなくなってきているそうです。手術の予定だったそうですが、医師より「原因がはっきりせず、危険を伴う個所なので、様子を見ている」そうです。原因がはっきりし、いやされますように、お祈りください。', 'C', 'brazil_diary_blogger'),
(7, 'トラクト配りに燃えてます', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post_03.html', '2011-09-03', 'ブラジル日記', 'こんにちは、エパタです。今日もトラクト配りに出かけました。UNIP(パウリスタ大学）の先生が話しかけてくださり、一生懸命英語で会話してくださいました。生徒さんに日系人の方がたくさんおられるとのことで、トラクト４部もらってくださいました。その方の知り合いの日系人の方を紹介していただき、ポルトガル語で福音を語り、トラクトをお渡ししました。日本で19年働いたそうです。日蓮宗だそうですが、福音をよく聞いてくださいました。また、日伯協会で顔見知りの日系のご婦人にばったり会い、トラクトをお渡ししました。主よ、これらの恵みを感謝します。トラクトが用いられますように。。。', 'こんにちは、エパタです。今日もトラクト配りに出かけました。UNIP(パウリスタ大学）の先生が話しかけてくださり、一生懸命英語で会話してくださいました。生徒さんに日系人の方がたくさんおられるとのことで、トラクト４部もらってくださいました。その方の知り合いの日系人の方を紹介していただき、ポルトガル語で福音を語り、トラクトをお渡ししました。日本で19年働いたそうです。日蓮宗だそうですが、福音をよく聞いてくださいました。また、日伯協会で顔見知りの日系のご婦人にばったり会い、トラクトをお渡ししました。主よ、これらの恵みを感謝します。トラクトが用いられますように。。。', 'C', 'brazil_diary_blogger'),
(8, '若者に渡しました', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post_04.html', '2011-09-04', 'ブラジル日記', 'こんにちは、エパタです。昨日書くつもりが今日になってしまいました。あの後、グァララペス教会に集っておられた日系人の方（奥様はブラジル人）がわが家を訪問してくださったので、伝道のために用いてほしいと、トラクトをお渡ししました。そして今日は、まさにターゲットかなと思う人に渡せました。14歳くらいの日系の男の子。（こんな感じの子が一人歩きしているのは珍しいです）彼自身にも興味ある内容だと思いますが、「日本語しか読めないおじいさん、おばあさんがいますか？」と聞くと、「いる」と言うので、「イエス様を受け入れるお祈りまでお願いしてね」とお渡ししました。そして、その後、以前にイエス様を受け入れた日系人の方の家の前を通ると、門に出てきておられたので（この方はまだ教会には来ていませんが）、トラクトをご友人に渡していただけるよう、差し上げました。主が導きに感謝します。主にすべてのご栄光をお返しします。', 'こんにちは、エパタです。昨日書くつもりが今日になってしまいました。あの後、グァララペス教会に集っておられた日系人の方（奥様はブラジル人）がわが家を訪問してくださったので、伝道のために用いてほしいと、トラクトをお渡ししました。そして今日は、まさにターゲットかなと思う人に渡せました。14歳くらいの日系の男の子。（こんな感じの子が一人歩きしているのは珍しいです）彼自身にも興味ある内容だと思いますが、「日本語しか読めないおじいさん、おばあさんがいますか？」と聞くと、「いる」と言うので、「イエス様を受け入れるお祈りまでお願いしてね」とお渡ししました。そして、その後、以前にイエス様を受け入れた日系人の方の家の前を通ると、門に出てきておられたので（この方はまだ教会には来ていませんが）、トラクトをご友人に渡していただけるよう、差し上げました。主が導きに感謝します。主にすべてのご栄光をお返しします。', 'C', 'brazil_diary_blogger'),
(9, '営業？！', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post_07.html', '2011-09-07', '宣伝・広告', 'こんにちは、エパタです。今日は政府直営の露天商街「カメロードロモ」へ行ってきました。クリスチャングッズを売り出しているブースが何件かあり、そのうちの二件にトラクト「The Search」を伝道用として用いていただけるように差し上げてきました。将来の売り物としてのサンプルの意味合いも込めつつ。（＾＾）', 'こんにちは、エパタです。今日は政府直営の露天商街「カメロードロモ」へ行ってきました。クリスチャングッズを売り出しているブースが何件かあり、そのうちの二件にトラクト「The Search」を伝道用として用いていただけるように差し上げてきました。将来の売り物としてのサンプルの意味合いも込めつつ。（＾＾）', 'C', 'brazil_diary_blogger'),
(10, '風邪が治ったそうです', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post_11.html', '2011-09-11', 'ブラジル日記', 'こんばんは、エパタです。イエス様を受け入れませんかとお誘いしている方が、風邪で咳をごほごほ、つらそうにしておられたので、いやしのために手を置いてお祈りしました。額に手を置いた時、やや熱かったので熱があるかなと思いましたが、祈っていると急に熱が下がったのを感じました。祈り終わった後、信じることが大事だよねと言われました。今日お電話をいただいたので、「風邪は治りましたか？」と聞くと、「たいしたことないよ」と全く普通の声でした。主にご栄光をお返しします。', 'こんばんは、エパタです。イエス様を受け入れませんかとお誘いしている方が、風邪で咳をごほごほ、つらそうにしておられたので、いやしのために手を置いてお祈りしました。額に手を置いた時、やや熱かったので熱があるかなと思いましたが、祈っていると急に熱が下がったのを感じました。祈り終わった後、信じることが大事だよねと言われました。今日お電話をいただいたので、「風邪は治りましたか？」と聞くと、「たいしたことないよ」と全く普通の声でした。主にご栄光をお返しします。', 'C', 'brazil_diary_blogger'),
(11, 'お祈りください', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post_24.html', '2011-09-24', 'ブラジル日記', 'ポルトガル語のクラスの先生のお父様、ウィルソンさんが、心臓の手術を受けられたのですが、手術そのものはうまくいったものの、ＩＣＵ（集中治療室）で脳卒中を起こし、一時、危ない状況になっていたそうです。今は、容態も落ち着き、快方に向かっておられますが、術後の心臓のため、長年の喫煙で弱っている肺が強められるように、また、脳卒中の後遺症がでないようにどうかお祈りください。', 'ポルトガル語のクラスの先生のお父様、ウィルソンさんが、心臓の手術を受けられたのですが、手術そのものはうまくいったものの、ＩＣＵ（集中治療室）で脳卒中を起こし、一時、危ない状況になっていたそうです。今は、容態も落ち着き、快方に向かっておられますが、術後の心臓のため、長年の喫煙で弱っている肺が強められるように、また、脳卒中の後遺症がでないようにどうかお祈りください。', 'C', 'brazil_diary_blogger'),
(12, 'いやしのためにお祈りください', 'https://tlccc-mission-bra.blogspot.com/2011/09/blog-post_6909.html', '2011-09-25', '祈り', 'こんにちは、エパタです。イエス様を救い主として受け入れられた日系人のOさんのお宅を訪問して、右半身の麻痺がいやされるように、お祈りしてきました。一緒にとても熱心に祈りを合わせてくれます。日本語が少しできますが、ポルトガル語のほうが流暢です。私もポルトガル語で祈るように努めていますが、私がつまると、単語を言ってくれたりして協力してくれます。さらに完全に治りますように、お祈りください。', 'こんにちは、エパタです。イエス様を救い主として受け入れられた日系人のOさんのお宅を訪問して、右半身の麻痺がいやされるように、お祈りしてきました。一緒にとても熱心に祈りを合わせてくれます。日本語が少しできますが、ポルトガル語のほうが流暢です。私もポルトガル語で祈るように努めていますが、私がつまると、単語を言ってくれたりして協力してくれます。さらに完全に治りますように、お祈りください。', 'C', 'brazil_diary_blogger'),
(13, 'パーキンソン病のいやしのためにお祈りください', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post.html', '2011-10-03', '祈り', 'こんにちは、エパタです。私がリオデジャネイロに住んでいた時に、マクドナルドで声をかけてきてくださったブラジル人の主婦の方Eさんに、久しぶりに電話してみました。スカイプで世界中ただで話せる時代ですが、ブラジル国内の電話料金はやはり目玉が飛び出る高さでした。彼女はプロテスタントの他教会の方です。以前アマゾン川河口の町パラー州のベレンに住んでおられて、その町にはたくさんの日本からの移民が入植していて、「あなたを見たら、思い出した。懐かしい」と声をかけてきてくださったのでした。お宅にも呼んでくださって、交わりを持っていましたが、最近パーキンソン病と診断されました。今は、息子さんの家で自宅療養しておられます。どうぞ、いやしのためにお祈りください。', 'こんにちは、エパタです。私がリオデジャネイロに住んでいた時に、マクドナルドで声をかけてきてくださったブラジル人の主婦の方Eさんに、久しぶりに電話してみました。スカイプで世界中ただで話せる時代ですが、ブラジル国内の電話料金はやはり目玉が飛び出る高さでした。彼女はプロテスタントの他教会の方です。以前アマゾン川河口の町パラー州のベレンに住んでおられて、その町にはたくさんの日本からの移民が入植していて、「あなたを見たら、思い出した。懐かしい」と声をかけてきてくださったのでした。お宅にも呼んでくださって、交わりを持っていましたが、最近パーキンソン病と診断されました。今は、息子さんの家で自宅療養しておられます。どうぞ、いやしのためにお祈りください。', 'C', 'brazil_diary_blogger'),
(14, 'やせることができますように', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post_03.html', '2011-10-03', 'ブラジル日記', 'グァララペス教会に以前来ておられたAさんに半年ぶりくらいに電話しました。甲状腺ホルモンの異常は、ほぼ癒されて、ほとんど症状はないくらいだけれど、お医者様の指示通り、薬を飲んでいます。午前中にだるくなったり、眠くなることがたまにあります。さらにこのごろストレスか、とても太ってしまったので、どうぞ、聖霊様の助けによって楽にやせることができるように、また完全に癒されますように、おとりなしください。', 'グァララペス教会に以前来ておられたAさんに半年ぶりくらいに電話しました。甲状腺ホルモンの異常は、ほぼ癒されて、ほとんど症状はないくらいだけれど、お医者様の指示通り、薬を飲んでいます。午前中にだるくなったり、眠くなることがたまにあります。さらにこのごろストレスか、とても太ってしまったので、どうぞ、聖霊様の助けによって楽にやせることができるように、また完全に癒されますように、おとりなしください。', 'C', 'brazil_diary_blogger'),
(15, 'お祈りをありがとうございました', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post_9253.html', '2011-10-03', 'ブラジル日記', 'ポルトガル語のクラスの先生のお父様、ウィルソンさんが、心臓の手術の後、ＩＣＵ（集中治療室）で脳卒中を起され、一時期、持ち直しておられましたが、亡くなられました。いやしのためにお祈りくださった皆様、お祈りをありがとうございました。残されたご家族のためにもどうかお祈りください。', 'ポルトガル語のクラスの先生のお父様、ウィルソンさんが、心臓の手術の後、ＩＣＵ（集中治療室）で脳卒中を起され、一時期、持ち直しておられましたが、亡くなられました。いやしのためにお祈りくださった皆様、お祈りをありがとうございました。残されたご家族のためにもどうかお祈りください。', 'C', 'brazil_diary_blogger'),
(16, 'トラクト配布♪', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post_05.html', '2011-10-05', 'ブラジル日記', '追加のトラクトをありがとうございます。かんかん照りの暑い日でしたが、暑いことを感謝していたら、雲が出てきました。神様が共にいてくださることを感じました。ポスティングということをやっていなかったなと思わされ、日系人の方が住んでいると思われる日本庭園風の家に一冊、ポストに入れさせていただきました。そして、いつもお世話になっている日本食のお店に5冊お願いしてきました。その後、ショッピングセンターで、7～8歳くらいの男の子のいる家族4人連れの奥様がベンチに座っておられたのでお渡ししました。お渡しした途端に読み始めておられました。主に感謝します。', '追加のトラクトをありがとうございます。かんかん照りの暑い日でしたが、暑いことを感謝していたら、雲が出てきました。神様が共にいてくださることを感じました。ポスティングということをやっていなかったなと思わされ、日系人の方が住んでいると思われる日本庭園風の家に一冊、ポストに入れさせていただきました。そして、いつもお世話になっている日本食のお店に5冊お願いしてきました。その後、ショッピングセンターで、7～8歳くらいの男の子のいる家族4人連れの奥様がベンチに座っておられたのでお渡ししました。お渡しした途端に読み始めておられました。主に感謝します。', 'C', 'brazil_diary_blogger'),
(17, 'ポスティングしました', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post_06.html', '2011-10-06', '宣教活動', 'こんばんは、エパタです。やり始めると、いろいろアイディアが浮かぶもので、電話帳で住んでいる家の周りの通りで、姓も名も日本名の住所を紙に書き出して、その家を目指してポスティングしてきました。ひっそりと地味に長くこの地域に暮らしている、という感じの家が多かったです。雨が降りそうでしたが、天候も守られました。さらに、オリエンタルな顔だちの15歳くらいの男の子が、学校名のプリントされたTシャツを着て、ウォークマンを聞きながら一人歩きしていたので、一冊あげました。歩き読みして去って行きました。主に感謝します。', 'こんばんは、エパタです。やり始めると、いろいろアイディアが浮かぶもので、電話帳で住んでいる家の周りの通りで、姓も名も日本名の住所を紙に書き出して、その家を目指してポスティングしてきました。ひっそりと地味に長くこの地域に暮らしている、という感じの家が多かったです。雨が降りそうでしたが、天候も守られました。さらに、オリエンタルな顔だちの15歳くらいの男の子が、学校名のプリントされたTシャツを着て、ウォークマンを聞きながら一人歩きしていたので、一冊あげました。歩き読みして去って行きました。主に感謝します。', 'C', 'brazil_diary_blogger'),
(18, '1日違いでブラジルへ', 'https://tlccc-mission-bra.blogspot.com/2011/10/290115.html', '2011-10-14', 'ブラジル日記', '日本から送っていただいた日本語のトラクトを、よく行くパステル屋のおじさんや、日本食料品店のおばさんなど、日系人の方にお渡ししています。ここアラサトゥーバからも日本に出稼ぎに行っていた方は多く、日本語を話せますが、読むのは難しいそうです。おばさんも、「私の両親は日本から来たから読めるけど、私はちょっとね」と言われたので、それならばぜひご両親に読んでいただいてください、とお渡ししました。また、昨日は銀行で用事を済ませた帰りに、のどが渇いたので、『オレンジジュース（ブラジルでは生のオレンジを絞ります）2レアル（約90円）』という貼り紙に引かれて、初めて入ったお店が、日系人の方のお店でした。話を聞くと、私が日本からブラジルに来たのと1日違いで、15年住んだ日本から戻ってきたという方たちでした。アラサトゥーバには日系人はたくさんいても、日本から来た日本人はいないので懐かしい！と言われ、遊びに来てくださいと言われました。日本ではコンサートでボサノバを歌っていたというその奥さんは、ギターも弾けるそうなので、一緒に賛美できたら♪と祈っています。', '日本から送っていただいた日本語のトラクトを、よく行くパステル屋のおじさんや、日本食料品店のおばさんなど、日系人の方にお渡ししています。ここアラサトゥーバからも日本に出稼ぎに行っていた方は多く、日本語を話せますが、読むのは難しいそうです。おばさんも、「私の両親は日本から来たから読めるけど、私はちょっとね」と言われたので、それならばぜひご両親に読んでいただいてください、とお渡ししました。また、昨日は銀行で用事を済ませた帰りに、のどが渇いたので、『オレンジジュース（ブラジルでは生のオレンジを絞ります）2レアル（約90円）』という貼り紙に引かれて、初めて入ったお店が、日系人の方のお店でした。話を聞くと、私が日本からブラジルに来たのと1日違いで、15年住んだ日本から戻ってきたという方たちでした。アラサトゥーバには日系人はたくさんいても、日本から来た日本人はいないので懐かしい！と言われ、遊びに来てくださいと言われました。日本ではコンサートでボサノバを歌っていたというその奥さんは、ギターも弾けるそうなので、一緒に賛美できたら♪と祈っています。', 'C', 'brazil_diary_blogger'),
(19, '日系人クリスチャンの方との出会い', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post_20.html', '2011-10-20', '宣伝・広告', 'こんばんは、エパタです。今日もトラクト配りに出かけました。けっこう今日の反応は、対応が厳しい方々が多く、めげそうになりました（汗）。ベンチに座り、祈ったり、聖書を読んだりした後、グァナー（清涼飲料）を飲んだお店が日系人の方だったので、トラクトをお渡しすることができました。すると、なんとクリスチャンでした。日本にも滞在されたことがおありで、名古屋で開催された外国人伝道者の集会に参加されたこともあるとのことでした。ブラジルで事業をするにあたっての苦労話をいろいろ聞かせていただきました。お店が祝福されますように。。。主よ、今日の一日を感謝します。', 'こんばんは、エパタです。今日もトラクト配りに出かけました。けっこう今日の反応は、対応が厳しい方々が多く、めげそうになりました（汗）。ベンチに座り、祈ったり、聖書を読んだりした後、グァナー（清涼飲料）を飲んだお店が日系人の方だったので、トラクトをお渡しすることができました。すると、なんとクリスチャンでした。日本にも滞在されたことがおありで、名古屋で開催された外国人伝道者の集会に参加されたこともあるとのことでした。ブラジルで事業をするにあたっての苦労話をいろいろ聞かせていただきました。お店が祝福されますように。。。主よ、今日の一日を感謝します。', 'C', 'brazil_diary_blogger'),
(20, '「やっぱり日本がいい」', 'https://tlccc-mission-bra.blogspot.com/2011/10/o20.html', '2011-10-23', 'ブラジル日記', 'こんにちは、エパタです。今日はトラクト配りの反応が良かったです(^O^)。天気も曇りにしてくださいと神様にお願いしたら、涼しい風まで吹いてきて、本当に共におられる神様に感謝しました。20代前半くらいの女性と、小学生くらいの男の子を連れたお母さんにお渡ししました。やはり、日本語で話しかけるのがポイントのようで、後者の方は、しばらく立ち話をしてくださいました。日本にも行かれたことがあって、「もうぜ～ったい、日本がいい」と言っておられました。用いられますように。トラクトが残りわずかとなってきましたが、御心の方に渡すことができますように。。。', 'こんにちは、エパタです。今日はトラクト配りの反応が良かったです(^O^)。天気も曇りにしてくださいと神様にお願いしたら、涼しい風まで吹いてきて、本当に共におられる神様に感謝しました。20代前半くらいの女性と、小学生くらいの男の子を連れたお母さんにお渡ししました。やはり、日本語で話しかけるのがポイントのようで、後者の方は、しばらく立ち話をしてくださいました。日本にも行かれたことがあって、「もうぜ～ったい、日本がいい」と言っておられました。用いられますように。トラクトが残りわずかとなってきましたが、御心の方に渡すことができますように。。。', 'C', 'brazil_diary_blogger'),
(21, '祈りの答え', 'https://tlccc-mission-bra.blogspot.com/2011/10/blog-post_30.html', '2011-10-30', 'ブラジル日記', 'こんばんは、エパタです。今日も暑い日でした。出かける時に、「暑くないようにしてください。雲が出てきますように。家に帰ってきた後に雨が降りますように」と祈りましたが、前半の祈りは答えられませんでした。暑いことを感謝し、日差しを感謝しつつ、歩いていると、即興で歌が出てきました。昔聞いたような、子供の歌で、メロディーだけなので、歌詞は「タラ～ララン」でずっと歌い続けて歩きました。すると、日系人の家族（父母と3，4歳くらいの男の子）が家に到着して車から降りて門の前に行くところに出くわしたので、トラクトを手渡すことができました。さらに、アラサトゥーバの繁華街の中にあるクリスチャンブックストア「ペニエル」に、2冊あげてきました。帰ってきた後雨が降り出し、最後の祈りは答えられました。涼しくなったと共に、家の周りの積もった木の葉などをきれいに掃除してくださいました。主の助けに感謝します。', 'こんばんは、エパタです。今日も暑い日でした。出かける時に、「暑くないようにしてください。雲が出てきますように。家に帰ってきた後に雨が降りますように」と祈りましたが、前半の祈りは答えられませんでした。暑いことを感謝し、日差しを感謝しつつ、歩いていると、即興で歌が出てきました。昔聞いたような、子供の歌で、メロディーだけなので、歌詞は「タラ～ララン」でずっと歌い続けて歩きました。すると、日系人の家族（父母と3，4歳くらいの男の子）が家に到着して車から降りて門の前に行くところに出くわしたので、トラクトを手渡すことができました。さらに、アラサトゥーバの繁華街の中にあるクリスチャンブックストア「ペニエル」に、2冊あげてきました。帰ってきた後雨が降り出し、最後の祈りは答えられました。涼しくなったと共に、家の周りの積もった木の葉などをきれいに掃除してくださいました。主の助けに感謝します。', 'C', 'brazil_diary_blogger'),
(22, '新しい友達', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post.html', '2011-11-06', 'ブラジル日記', 'こんにちは、エパタです。トラクトを配った家を訪問してみました。その中に日系人の旦那様をなくされたばかりのLさんがいました。彼女はクリスチャンでもうかなり悲しみは乗り越えた様子でしたが、私自身のポルトガル語の練習のためにも、何か共通の話題が与えられますように祈っています。', 'こんにちは、エパタです。トラクトを配った家を訪問してみました。その中に日系人の旦那様をなくされたばかりのLさんがいました。彼女はクリスチャンでもうかなり悲しみは乗り越えた様子でしたが、私自身のポルトガル語の練習のためにも、何か共通の話題が与えられますように祈っています。', 'C', 'brazil_diary_blogger'),
(23, '宣教の働きへの献品', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post_07.html', '2011-11-07', 'ブラジル日記', 'こんにちは、エパタです。他教会のご夫婦が「宣教の働きのために」と、アンプ１台、マイク２本を提供してくださいました。感謝いたします。主の豊かな祝福がご夫妻の上にありますように。', 'こんにちは、エパタです。他教会のご夫婦が「宣教の働きのために」と、アンプ１台、マイク２本を提供してくださいました。感謝いたします。主の豊かな祝福がご夫妻の上にありますように。', 'C', 'brazil_diary_blogger'),
(24, '救いのみわざ！', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post_4029.html', '2011-11-07', 'ブラジル日記', 'こんにちは、エパタです。懇意にしてくださっている方が新年礼拝にきてくださいました。非常にはっきりした福音がメッセージの中で語られ、大きな声でイエス様を救い主として告白されました。「新しい希望ができました」と言っておられました。主に栄光をお返しします。皆様のおとりなしを心より感謝いたします。', 'こんにちは、エパタです。懇意にしてくださっている方が新年礼拝にきてくださいました。非常にはっきりした福音がメッセージの中で語られ、大きな声でイエス様を救い主として告白されました。「新しい希望ができました」と言っておられました。主に栄光をお返しします。皆様のおとりなしを心より感謝いたします。', 'C', 'brazil_diary_blogger'),
(25, 'トラクトを日本語が読める方に渡せました！', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post_10.html', '2011-11-10', '宣教活動', 'こんにちは、エパタです。先日、アンプとマイクを献品してくださったご夫妻が、お住まいの家のとなりの日系の方にトラクトを渡してくださいました。私もちょうどその場にいたのですが、「道を探して」とその場で声を出して読んでおられました。さらに主の導きがありますようにと、祈ります。', 'こんにちは、エパタです。先日、アンプとマイクを献品してくださったご夫妻が、お住まいの家のとなりの日系の方にトラクトを渡してくださいました。私もちょうどその場にいたのですが、「道を探して」とその場で声を出して読んでおられました。さらに主の導きがありますようにと、祈ります。', 'C', 'brazil_diary_blogger'),
(26, 'ブラジル人が参加してくださいました！', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post_16.html', '2011-11-16', 'ブラジル日記', 'こんばんは、エパタです。トレンディなのか、ブラジルでもPCがダウン。しばらく更新できませんでした。しかし、主のみわざは進んでいます！　先週の賛美隊では、アラサトゥーバで初めてブラジル人が参加して歌ってくださいました。ハレルヤ！！<br /><div class="separator" style="clear: both; text-align: center;"><a href="http://3.bp.blogspot.com/-aiOq4HTl-BA/TsMPgDQ1faI/AAAAAAAAAMM/FfmBAQ9rJxo/s1600/IMG0081A.jpg"><img border="0" height="240" width="320" src="http://3.bp.blogspot.com/-aiOq4HTl-BA/TsMPgDQ1faI/AAAAAAAAAMM/FfmBAQ9rJxo/s400/IMG0081A.jpg" /></a></div>', 'こんばんは、エパタです。トレンディなのか、ブラジルでもPCがダウン。しばらく更新できませんでした。しかし、主のみわざは進んでいます！　先週の賛美隊では、アラサトゥーバで初めてブラジル人が参加して歌ってくださいました。ハレルヤ！！', 'C', 'brazil_diary_blogger'),
(27, '歌集が届きました', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post_23.html', '2011-11-23', 'ブラジル日記', '日本からSAL便で送っていただいた「やすらぎの歌 第11集」が、ちょうど3週間でブラジルにも届きました。<br /><br /><div class="separator" style="clear: both; text-align: center;"><a href="http://4.bp.blogspot.com/-2ZST7qxrEGw/Tsw4iXy8KAI/AAAAAAAAANA/gN7ECTbE3c0/s1600/IMG_3546.JPG"><img border="0" height="240" width="320" src="http://4.bp.blogspot.com/-2ZST7qxrEGw/Tsw4iXy8KAI/AAAAAAAAANA/gN7ECTbE3c0/s400/IMG_3546.JPG" /></a></div><br />新しい歌を主に歌え。全地よ。主に歌え。主に歌え。御名をほめたたえよ。（詩篇96：1－2）', '日本からSAL便で送っていただいた「やすらぎの歌 第11集」が、ちょうど3週間でブラジルにも届きました。


新しい歌を主に歌え。全地よ。主に歌え。主に歌え。御名をほめたたえよ。（詩篇96：1－2）', 'C', 'brazil_diary_blogger'),
(28, '糖尿病と高血圧のためにお祈りください', 'https://tlccc-mission-bra.blogspot.com/2011/11/blog-post_27.html', '2011-11-27', 'ブラジル日記', 'こんばんは、エパタです。以前グァララペスで訪問して癒しのために祈っていた方に、久しぶりに電話することができました。私がブラジルに来たばかりの時住んだことのあるジャンジーラに、ほとんどの家族・親類がおられる方で、電話したことをとても喜んでくださって、どうして家に来ない、今週来なさいと誘ってくださいました。糖尿病と高血圧をわずらっておられて、以前血糖値が著しく下がった時があったのですが、今また上がりぎみだそうです。どうぞ、癒しのためにお祈りください。', 'こんばんは、エパタです。以前グァララペスで訪問して癒しのために祈っていた方に、久しぶりに電話することができました。私がブラジルに来たばかりの時住んだことのあるジャンジーラに、ほとんどの家族・親類がおられる方で、電話したことをとても喜んでくださって、どうして家に来ない、今週来なさいと誘ってくださいました。糖尿病と高血圧をわずらっておられて、以前血糖値が著しく下がった時があったのですが、今また上がりぎみだそうです。どうぞ、癒しのためにお祈りください。', 'C', 'brazil_diary_blogger'),
(29, 'オンライン礼拝の恵み', 'https://tlccc-mission-bra.blogspot.com/2011/12/blog-post.html', '2011-12-18', 'ブラジル日記', 'ブラジルにいながらにして、千葉の田舎で近くに教会がなく、礼拝に行くことができない母と、今日初めて東京アンテオケ教会のオンライン礼拝に、一緒に参加しています。こんな日が来るとは！　21世紀の宣教師の恵みです。主にご栄光をお返しします。', 'ブラジルにいながらにして、千葉の田舎で近くに教会がなく、礼拝に行くことができない母と、今日初めて東京アンテオケ教会のオンライン礼拝に、一緒に参加しています。こんな日が来るとは！　21世紀の宣教師の恵みです。主にご栄光をお返しします。', 'C', 'brazil_diary_blogger'),
(30, 'やすらぎ of 歌をポルトガル語で賛美', 'https://tlccc-mission-bra.blogspot.com/2011/12/blog-post_22.html', '2011-12-22', 'ブラジル日記', 'こんばんは、エパタです。やすらぎの歌11集の10番「Grace of Jesus」を勝手にポルトガル語にして、路傍賛美しました。ポルトガル語は字余りするので、直訳はできませんが、だいたいで歌わせていただいています。慣れると、この字余りも味があって、いいです。jesus は英語だと、「ジーザス」で、二拍分ですが、ポルトガル語では、「ジェーズース」と三拍です。', 'こんばんは、エパタです。やすらぎの歌11集の10番「Grace of Jesus」を勝手にポルトガル語にして、路傍賛美しました。ポルトガル語は字余りするので、直訳はできませんが、だいたいで歌わせていただいています。慣れると、この字余りも味があって、いいです。jesus は英語だと、「ジーザス」で、二拍分ですが、ポルトガル語では、「ジェーズース」と三拍です。', 'C', 'brazil_diary_blogger'),
(31, 'トラクトを連邦警察の方にお渡ししました', 'https://tlccc-mission-bra.blogspot.com/2011/12/blog-post_5350.html', '2011-12-22', '宣教活動', 'こんばんは、エパタです。アラサトゥーバの連邦警察にお勤めのEさんは、なんと、名字が日本名。近くの中華レストランでもばったりお会いしたことがありました。一瞬躊躇したのですが、勇気を奮って、日本語の漫画トラクトをお渡してきました。しっかり電話番号も書きました。ご親戚の中に救われる方が起こされますように。。。', 'こんばんは、エパタです。アラサトゥーバの連邦警察にお勤めのEさんは、なんと、名字が日本名。近くの中華レストランでもばったりお会いしたことがありました。一瞬躊躇したのですが、勇気を奮って、日本語の漫画トラクトをお渡してきました。しっかり電話番号も書きました。ご親戚の中に救われる方が起こされますように。。。', 'C', 'brazil_diary_blogger'),
(32, '路傍賛美に行ってきました', 'https://tlccc-mission-bra.blogspot.com/2011/12/blog-post_25.html', '2011-12-25', 'ブラジル日記', 'こんにちは、エパタです。やすらぎの歌１０集の２１番と６１番、１１集の１番と１０番などに、勝手にポルトガル語で歌詞をつけて、いつもの所へ行って歌ってきました。その後、いつもオンライン礼拝などで歌っている日本語の歌も歌いましたが、日本語のほうが自由に主に心を向けて礼拝することができました。しかしさらに新しい曲のポルトガル語の賛美を主に祈り求めたいと思います。', 'こんにちは、エパタです。やすらぎの歌１０集の２１番と６１番、１１集の１番と１０番などに、勝手にポルトガル語で歌詞をつけて、いつもの所へ行って歌ってきました。その後、いつもオンライン礼拝などで歌っている日本語の歌も歌いましたが、日本語のほうが自由に主に心を向けて礼拝することができました。しかしさらに新しい曲のポルトガル語の賛美を主に祈り求めたいと思います。', 'C', 'brazil_diary_blogger'),
(33, '日本語くらす', 'https://tlccc-mission-bra.blogspot.com/2011/12/blog-post_31.html', '2011-12-31', 'ブラジル日記', 'こんばんは、エパタです。今日はスーパーに行ったら、レジのところで店員さんと日系人のお客さんが会話していました。最後に店員さんが「さようなら！」と言って、次のお客さんに「そのうち日本語がペラペラになるよ～～」と話していました。そこで、自分の番が来た時に、「もしよかったら、日本語教えますよ」と言って、電話番号をいただきました。主よ、どうぞ御心の電話ができますように。。。楽しく日本語を教えつつ、伝道ができますように。。。', 'こんばんは、エパタです。今日はスーパーに行ったら、レジのところで店員さんと日系人のお客さんが会話していました。最後に店員さんが「さようなら！」と言って、次のお客さんに「そのうち日本語がペラペラになるよ～～」と話していました。そこで、自分の番が来た時に、「もしよかったら、日本語教えますよ」と言って、電話番号をいただきました。主よ、どうぞ御心の電話ができますように。。。楽しく日本語を教えつつ、伝道ができますように。。。', 'C', 'brazil_diary_blogger'),
(34, '大雨の中', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post.html', '2012-01-01', 'ブラジル日記', 'こんばんは、エパタです。今日はすさまじい大雨の中、恵みの雨を感謝しつつ、路傍賛美隊に行ってきました。いつも同じ場所にいて見張っている私服警官の方もいて、あいさつしました。それから、トラクトを渡したお店を経営している方を訪問して、トラクトを誰かにあげたか聞きました。「車の中にある。みんなに見せている」そうで、「それはあげていいです」ともう一冊お渡ししました。御心の方へトラクトが手渡されますように。この方のご商売が主にあって祝福されますように。。。', 'こんばんは、エパタです。今日はすさまじい大雨の中、恵みの雨を感謝しつつ、路傍賛美隊に行ってきました。いつも同じ場所にいて見張っている私服警官の方もいて、あいさつしました。それから、トラクトを渡したお店を経営している方を訪問して、トラクトを誰かにあげたか聞きました。「車の中にある。みんなに見せている」そうで、「それはあげていいです」ともう一冊お渡ししました。御心の方へトラクトが手渡されますように。この方のご商売が主にあって祝福されますように。。。', 'C', 'brazil_diary_blogger'),
(35, 'トラクトをお願いしてきました', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post_05.html', '2012-01-05', 'ブラジル日記', 'こんにちは、エパタです。アラサトゥーバの唯一（だと思うのですが）日本食専門店だるま様にトラクトを置かせてもらってきました。<div class="separator" style="clear: both; text-align: center;"><a href="http://2.bp.blogspot.com/-zbiloATw2F4/TwSVgluBIVI/AAAAAAAAAS4/G2cbdZGF8Yk/s1600/Imagem.jpg"><img border="0" height="150" width="200" src="http://2.bp.blogspot.com/-zbiloATw2F4/TwSVgluBIVI/AAAAAAAAAS4/G2cbdZGF8Yk/s200/Imagem.jpg" /></a></div>カウンターの所に置いてあります。用いられますように。また、お店が祝福されますように。<br /><br />DARUMA / Rua Torres Homem, 288 - Araçatuba-SP / Tel: 55-18-3622-8904', 'こんにちは、エパタです。アラサトゥーバの唯一（だと思うのですが）日本食専門店だるま様にトラクトを置かせてもらってきました。カウンターの所に置いてあります。用いられますように。また、お店が祝福されますように。

DARUMA / Rua Torres Homem, 288 - Araçatuba-SP / Tel: 55-18-3622-8904', 'C', 'brazil_diary_blogger'),
(36, '賛美隊、祝福されました！', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post_08.html', '2012-01-08', 'ブラジル日記', 'こんにちは、エパタです。へっぴり腰で周囲を伺いつつでしたが、いつもの場所で、賛美の声、喜びの声を上げ始めたところ、「最近教会から離れていたが、教会に戻りたいとは思っていた」という10代後半ぐらいの男の子を含め、4名が賛美隊の働きに参加しました！！　ハレルヤ！！', 'こんにちは、エパタです。へっぴり腰で周囲を伺いつつでしたが、いつもの場所で、賛美の声、喜びの声を上げ始めたところ、「最近教会から離れていたが、教会に戻りたいとは思っていた」という10代後半ぐらいの男の子を含め、4名が賛美隊の働きに参加しました！！　ハレルヤ！！', 'C', 'brazil_diary_blogger'),
(37, '補充してきました', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post_15.html', '2012-01-15', '宣伝・広告', 'こんばんは、エパタです。今、すさまじいスコールと雷雨です。今日は日本食のお店にトラクトを３冊補充してきました。お願いしたもの全部あげてくださったとのことで、感謝します。さらにお店が祝福されますように。。。', 'こんばんは、エパタです。今、すさまじいスコールと雷雨です。今日は日本食のお店にトラクトを３冊補充してきました。お願いしたもの全部あげてくださったとのことで、感謝します。さらにお店が祝福されますように。。。', 'C', 'brazil_diary_blogger'),
(38, '日本語クラスの授業やりました', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post_17.html', '2012-01-17', '日本語クラス', 'こんにちは、エパタです。ひさ～～しぶりに日本語を教えました。昨日ガイダンスを受けに来たブラジル人の女の子たち、二人です。今までいろいろな人に教えましたが、やっぱり「あいうえお」が一番大事で、これに尽きるなと思わされました。とにかくひらがなだけ覚えてもらって、次は、一緒に「やすらぎの歌」を歌いたいと思います。', 'こんにちは、エパタです。ひさ～～しぶりに日本語を教えました。昨日ガイダンスを受けに来たブラジル人の女の子たち、二人です。今までいろいろな人に教えましたが、やっぱり「あいうえお」が一番大事で、これに尽きるなと思わされました。とにかくひらがなだけ覚えてもらって、次は、一緒に「やすらぎの歌」を歌いたいと思います。', 'C', 'brazil_diary_blogger'),
(39, '日本語クラスで「やすらぎの歌」チャレンジしました！', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post_20.html', '2012-01-20', 'ゴスペル', 'おはようございます、エパタです。今週の月曜日から日本語を教え始めました。やっぱりブラジル人、歌が好きで、一日ひらがなに関する説明をしただけで、もう二回目の水曜日には日本語の歌を歌おう！　ということになりました。そこで、「やすらぎの歌」をチャレンジしてみました。楽譜はひらがなばかりですから、本当に助かります。今歌っているのは、「永遠の愛」と「Grace of Jesus」です。「Grace of Jesus」は、ボーカロイドみたいなノリで、歌いやすいです。ポルトガル語を話す人々の場合、「ここ」「こころ」「かがやく」などの言葉はNGなのです。。。', 'おはようございます、エパタです。今週の月曜日から日本語を教え始めました。やっぱりブラジル人、歌が好きで、一日ひらがなに関する説明をしただけで、もう二回目の水曜日には日本語の歌を歌おう！　ということになりました。そこで、「やすらぎの歌」をチャレンジしてみました。楽譜はひらがなばかりですから、本当に助かります。今歌っているのは、「永遠の愛」と「Grace of Jesus」です。「Grace of Jesus」は、ボーカロイドみたいなノリで、歌いやすいです。ポルトガル語を話す人々の場合、「ここ」「こころ」「かがやく」などの言葉はNGなのです。。。', 'C', 'brazil_diary_blogger'),
(40, '日本語くらす', 'https://tlccc-mission-bra.blogspot.com/2012/01/blog-post_31.html', '2012-01-31', 'ブラジル日記', 'こんばんは、エパタです。お久しぶりで、すみません（汗）。今日は日本語を学びに女の子たちが来てくれました。これで、私も励まされています。以前メシアニックジューで元プロの歌手だった牧師さんがプレゼントしてくれたボイストレーニングのCDを引っ張り出し、本格的にゴスペルクラブとなるか！？', 'こんばんは、エパタです。お久しぶりで、すみません（汗）。今日は日本語を学びに女の子たちが来てくれました。これで、私も励まされています。以前メシアニックジューで元プロの歌手だった牧師さんがプレゼントしてくれたボイストレーニングのCDを引っ張り出し、本格的にゴスペルクラブとなるか！？', 'C', 'brazil_diary_blogger'),
(41, '職場で「やすらぎの歌」を歌っているそうです', 'https://tlccc-mission-bra.blogspot.com/2012/02/blog-post.html', '2012-02-04', 'ゴスペル', 'こんばんは、エパタです。今日も日本語くらすに女の子たちが来てくれました。イエス様は受け入れているそうですが、お祈りするのは「いや」だと断られてしまいました。私が祈る時にはおとなしく聞いていてくれるのですが。でも、やはり歌が気に入っているようで、「職場でもこの歌を二人で歌ってるんだよ～～」と言ってました。やすらぎの歌が職場でも用いられています。', 'こんばんは、エパタです。今日も日本語くらすに女の子たちが来てくれました。イエス様は受け入れているそうですが、お祈りするのは「いや」だと断られてしまいました。私が祈る時にはおとなしく聞いていてくれるのですが。でも、やはり歌が気に入っているようで、「職場でもこの歌を二人で歌ってるんだよ～～」と言ってました。やすらぎの歌が職場でも用いられています。', 'C', 'brazil_diary_blogger'),
(42, '「The Search」の配布を完了！', 'https://tlccc-mission-bra.blogspot.com/2012/02/search.html', '2012-02-27', '宣伝・広告', 'こんばんは、エパタです。ご無沙汰してしまいました。お分けいただいたトラクト「The Search」をブラジル教会の分はすべて配布完了しました！　Praise the Lord! 昨日最後の４冊をいつもお世話になっている日本食専門店に配布をお願いしてきました。マンガトラクトなのが、本当にうれしいです。自分用として一冊取っておきたくなりましたが、思い切って全部お願いしてきました。主よ、用いてください。', 'こんばんは、エパタです。ご無沙汰してしまいました。お分けいただいたトラクト「The Search」をブラジル教会の分はすべて配布完了しました！　Praise the Lord! 昨日最後の４冊をいつもお世話になっている日本食専門店に配布をお願いしてきました。マンガトラクトなのが、本当にうれしいです。自分用として一冊取っておきたくなりましたが、思い切って全部お願いしてきました。主よ、用いてください。', 'C', 'brazil_diary_blogger'),
(43, 'ブラジルチームが遣わされます', 'https://tlccc-mission-bra.blogspot.com/2012/03/blog-post.html', '2012-03-23', 'チーム', '５月２１日から２６日まで、聖所から流れ出る水ミッションよりブラジルチームが遣わされます。サンパウロとリオデジャネイロでの集会が持たれます。どうぞ、お祈りください。The evangelistic team to Brazil will be sent on May 21th to 26th.', '５月２１日から２６日まで、聖所から流れ出る水ミッションよりブラジルチームが遣わされます。サンパウロとリオデジャネイロでの集会が持たれます。どうぞ、お祈りください。The evangelistic team to Brazil will be sent on May 21th to 26th.', 'C', 'brazil_diary_blogger'),
(44, '髪を切っていただきました', 'https://tlccc-mission-bra.blogspot.com/2012/04/blog-post.html', '2012-04-01', 'ブラジル日記', 'こんばんは、エパタです。「The Search」のトラクト配布の際に知り合ったLさんにまた電話してみました。彼女は日系人のご主人を最近亡くされた方です。話していると、彼女は自宅にサロンを持っておられて、髪を切ってくださると聞きました。実は私はけっこう髪が長くなり過ぎていましたが、いつも4レアルで切っていただいていたサロンが閉店になってしまい、そのままになっていました。10レアルで切ってくださるということで、早速切っていただきました。今まではいつもストレートにしか表現できなかったのですが、段をつけてとても素敵に切ってくださいました。感謝します。', 'こんばんは、エパタです。「The Search」のトラクト配布の際に知り合ったLさんにまた電話してみました。彼女は日系人のご主人を最近亡くされた方です。話していると、彼女は自宅にサロンを持っておられて、髪を切ってくださると聞きました。実は私はけっこう髪が長くなり過ぎていましたが、いつも4レアルで切っていただいていたサロンが閉店になってしまい、そのままになっていました。10レアルで切ってくださるということで、早速切っていただきました。今まではいつもストレートにしか表現できなかったのですが、段をつけてとても素敵に切ってくださいました。感謝します。', 'C', 'brazil_diary_blogger'),
(45, '日系人クリスチャンのお店に行ってきました', 'https://tlccc-mission-bra.blogspot.com/2012/04/blog-post_02.html', '2012-04-02', '宣伝・広告', 'こんばんは、エパタです。以前トラクト「The Search」の配布を２冊お願いした店に行ってきました。オーナーさんは日系人クリスチャンで、お店はセントロの繁華街の中にあります。日本にも４年滞在したことがあります。トラクトは２冊とも配布してくださったそうです。お店で学校帰りらしく、学校のTシャツを着てお孫さんがお絵かきをしていたので、少し話をしました。「日本語習いたい？」と聞いたら、元気良く「やだ！（NAO）」と言われてしまいました。なんとか、お友達になれますように。。。', 'こんばんは、エパタです。以前トラクト「The Search」の配布を２冊お願いした店に行ってきました。オーナーさんは日系人クリスチャンで、お店はセントロの繁華街の中にあります。日本にも４年滞在したことがあります。トラクトは２冊とも配布してくださったそうです。お店で学校帰りらしく、学校のTシャツを着てお孫さんがお絵かきをしていたので、少し話をしました。「日本語習いたい？」と聞いたら、元気良く「やだ！（NAO）」と言われてしまいました。なんとか、お友達になれますように。。。', 'C', 'brazil_diary_blogger'),
(46, 'サンパウロに電話しました', 'https://tlccc-mission-bra.blogspot.com/2012/04/blog-post_12.html', '2012-04-12', 'ブラジル日記', 'おはようございます、エパタです。昨日はサンパウロでいつもお世話になっていた日本人の方Tさんに、三年以上ぶりに電話しました。電話は変わっていませんでした。奥様が変わらぬお元気な様子でした。み声新聞の大ファンで、いつも送らせていただいているのですが、「お父さんが喜んで読んでますよ」とのことでした。', 'おはようございます、エパタです。昨日はサンパウロでいつもお世話になっていた日本人の方Tさんに、三年以上ぶりに電話しました。電話は変わっていませんでした。奥様が変わらぬお元気な様子でした。み声新聞の大ファンで、いつも送らせていただいているのですが、「お父さんが喜んで読んでますよ」とのことでした。', 'C', 'brazil_diary_blogger'),
(47, '日本食専門店へ', 'https://tlccc-mission-bra.blogspot.com/2012/04/blog-post_16.html', '2012-04-16', '児童養護施設', 'こんにちは、エパタです。いつもトラクトを置いていただき、もう50冊近く配布に協力してくださった日本食専門店に、今度は日本児童養護施設の寄付金のアピールをお願いしてきました。なんと、オーナーの方、Sさんは福島県出身で、しかも相馬郡に隣接した郡の出身だそうです。主の豊かな祝福がありますように。。。', 'こんにちは、エパタです。いつもトラクトを置いていただき、もう50冊近く配布に協力してくださった日本食専門店に、今度は日本児童養護施設の寄付金のアピールをお願いしてきました。なんと、オーナーの方、Sさんは福島県出身で、しかも相馬郡に隣接した郡の出身だそうです。主の豊かな祝福がありますように。。。', 'C', 'brazil_diary_blogger'),
(48, 'ホテルのレストランへ', 'https://tlccc-mission-bra.blogspot.com/2012/04/blog-post_8961.html', '2012-04-16', '児童養護施設', 'こんばんは、エパタです。日本児童養護施設の寄付金のアピール（ポルトガル語）を10部、アラサトゥーバでは一番大きく一番有名なPホテルのレストランのカウンターに置いていただけるようにお願いしてきました。ホテルおよびレストランが祝福されますように。。。また御心の方が取って、献金してくださいますように。。。', 'こんばんは、エパタです。日本児童養護施設の寄付金のアピール（ポルトガル語）を10部、アラサトゥーバでは一番大きく一番有名なPホテルのレストランのカウンターに置いていただけるようにお願いしてきました。ホテルおよびレストランが祝福されますように。。。また御心の方が取って、献金してくださいますように。。。', 'C', 'brazil_diary_blogger'),
(49, '「雲の間にある虹5月号」が届きました！', 'https://tlccc-mission-bra.blogspot.com/2012/04/5.html', '2012-04-21', 'ブラジル日記', 'おはようございます、エパタです。昨日、「雲の間にある虹5月号」が届きました！　ありがとうございます。今回はアラサトゥーバでイエス様を受け入れた劉長生さんのインタビューも掲載されています。劉さんは90台湾生まれ。40歳を過ぎてブラジルに渡り、大事業を興されましたが、戦争体験がおありで、「銃弾降り注ぐ中を生きてきた。今日命があるのは、ただ天の神様の御助けだ」と実感して、イエス様を受け入れる決心をなされました。どうぞ、お買い求めくださり、伝道のためにお用いください。', 'おはようございます、エパタです。昨日、「雲の間にある虹5月号」が届きました！　ありがとうございます。今回はアラサトゥーバでイエス様を受け入れた劉長生さんのインタビューも掲載されています。劉さんは90台湾生まれ。40歳を過ぎてブラジルに渡り、大事業を興されましたが、戦争体験がおありで、「銃弾降り注ぐ中を生きてきた。今日命があるのは、ただ天の神様の御助けだ」と実感して、イエス様を受け入れる決心をなされました。どうぞ、お買い求めくださり、伝道のためにお用いください。', 'C', 'brazil_diary_blogger'),
(50, '雲の間にある虹を贈呈しました', 'https://tlccc-mission-bra.blogspot.com/2012/04/blog-post_25.html', '2012-04-25', '児童養護施設', 'こんばんは、エパタです。送っていただいた「雲の間にある虹」を、取材に協力してくださった劉さんに一冊、言及させていただいた大家さんに一冊ずつ、お渡ししました。とても喜んでくださいました。また大家さんに「日本児童養護施設の寄付のお願い」もお渡ししました。興味深げに読んでくださり、ブラジルでの子供たちのための働きにも協力を申し出てくださいました。感謝いたします。', 'こんばんは、エパタです。送っていただいた「雲の間にある虹」を、取材に協力してくださった劉さんに一冊、言及させていただいた大家さんに一冊ずつ、お渡ししました。とても喜んでくださいました。また大家さんに「日本児童養護施設の寄付のお願い」もお渡ししました。興味深げに読んでくださり、ブラジルでの子供たちのための働きにも協力を申し出てくださいました。感謝いたします。', 'C', 'brazil_diary_blogger'),
(51, 'もう20部お願いしてきました', 'https://tlccc-mission-bra.blogspot.com/2012/04/20.html', '2012-04-26', '児童養護施設', 'こんばんは、エパタです。「日本の児童養護施設への寄付のお願い」のポルトガル語を20部、アラサトゥーバで一番大きくて有名なホテルのレストランへ置いていただけるように、お願いしてきました。支配人の方が変わっていて、もう一度説明したら、「各テーブルに配布はできませんよ、カウンターに置くだけですよ」とおっしゃいました。「そんな、カウンターの端っこに置いていただければいいです」と答えました。豊かな主の祝福がこのレストランとホテルにありますように。。。', 'こんばんは、エパタです。「日本の児童養護施設への寄付のお願い」のポルトガル語を20部、アラサトゥーバで一番大きくて有名なホテルのレストランへ置いていただけるように、お願いしてきました。支配人の方が変わっていて、もう一度説明したら、「各テーブルに配布はできませんよ、カウンターに置くだけですよ」とおっしゃいました。「そんな、カウンターの端っこに置いていただければいいです」と答えました。豊かな主の祝福がこのレストランとホテルにありますように。。。', 'C', 'brazil_diary_blogger'),
(52, '追加をお願いしてきました', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post.html', '2012-05-02', '児童養護施設', 'こんばんは！エパタです。「日本の児童養護施設への寄付のお願い」のポルトガル語を17部、アラサトゥーバ一の有名ホテルつきレストランへ、追加配布をお願いしてきました。一番目につくところにで～～んと置いてくださり、これならすぐなくなるなと思いました。ブラジルは世界長者番付の上位に並ぶ大富豪もいますし、特にこのアラサトゥーバは自家用飛行機を持っているような方々が住んでいるそうです。日本の児童養護施設の詳しい規定についてや、土地の単位など、興味深いことが書いてあるので、支払いの際にちらっと目が行けば、読みたくなる内容です。本当に主はすばらしい計画を持っておられます。わくわくします。さらにこのレストランとホテルが主イエス・キリストによって祝福されますように。。。', 'こんばんは！エパタです。「日本の児童養護施設への寄付のお願い」のポルトガル語を17部、アラサトゥーバ一の有名ホテルつきレストランへ、追加配布をお願いしてきました。一番目につくところにで～～んと置いてくださり、これならすぐなくなるなと思いました。ブラジルは世界長者番付の上位に並ぶ大富豪もいますし、特にこのアラサトゥーバは自家用飛行機を持っているような方々が住んでいるそうです。日本の児童養護施設の詳しい規定についてや、土地の単位など、興味深いことが書いてあるので、支払いの際にちらっと目が行けば、読みたくなる内容です。本当に主はすばらしい計画を持っておられます。わくわくします。さらにこのレストランとホテルが主イエス・キリストによって祝福されますように。。。', 'C', 'brazil_diary_blogger'),
(53, '「雲の間にある虹」を読んだという人が現れました！', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_02.html', '2012-05-02', '宣伝・広告', 'エパタです！　月刊「雲の間にある虹」５月号のインタビューをさせていただいた劉長生さんによりますと、「あなたが劉長生さんですか。あの記事を読みました」と言って尋ねてきた人があったそうです！いろいろな人に尋ねて探し当てて来たのだそうです。中年の男性だったそうです。劉さんはてっきりその方が私の知り合いだと思っていました。（知りません）「雲の間にある虹」が読まれています！', 'エパタです！　月刊「雲の間にある虹」５月号のインタビューをさせていただいた劉長生さんによりますと、「あなたが劉長生さんですか。あの記事を読みました」と言って尋ねてきた人があったそうです！いろいろな人に尋ねて探し当てて来たのだそうです。中年の男性だったそうです。劉さんはてっきりその方が私の知り合いだと思っていました。（知りません）「雲の間にある虹」が読まれています！', 'C', 'brazil_diary_blogger'),
(54, '今度は３０部！', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_06.html', '2012-05-06', '児童養護施設', 'こんにちは、エパタです。「日本の児童養護施設への寄付のお願い」のポルトガル語を日本食専門店へ持っていきました。先日は持っていたのが３部で、全部お願いしてきましたが、今日は３０部！　お願いしてきました。前回はオーナーの方に渡しましたが、今度は娘さんに渡しました。良く見えるようにセッティングしてくださり、撮影許可、インターネット掲載許可もくださいました。携帯で撮ったのであまりよく写っていませんが、広くてきれいなお店です。お店が主イエス・キリストによって豊かに祝福されますように。', 'こんにちは、エパタです。「日本の児童養護施設への寄付のお願い」のポルトガル語を日本食専門店へ持っていきました。先日は持っていたのが３部で、全部お願いしてきましたが、今日は３０部！　お願いしてきました。前回はオーナーの方に渡しましたが、今度は娘さんに渡しました。良く見えるようにセッティングしてくださり、撮影許可、インターネット掲載許可もくださいました。携帯で撮ったのであまりよく写っていませんが、広くてきれいなお店です。お店が主イエス・キリストによって豊かに祝福されますように。', 'C', 'brazil_diary_blogger'),
(55, 'サンパウロ集会', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_08.html', '2012-05-08', 'ブラジル日記', 'サンパウロ集会の場所が決まりました。No dia 22 de maio de 2012, @ Igreja Assembréia de Deus, Ministério de Taubaté. São José dos Campos - SP.', 'サンパウロ集会の場所が決まりました。No dia 22 de maio de 2012, @ Igreja Assembréia de Deus, Ministério de Taubaté. São José dos Campos - SP.', 'C', 'brazil_diary_blogger'),
(56, 'リオ集会', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_9227.html', '2012-05-08', 'ブラジル日記', 'リオデジャネイロ集会が行われます。No dia 24 de maio de 2012. Centro Evangelístico Internacional. Rua Lemos Cunha 577, Icaraí. Niterói-RJ', 'リオデジャネイロ集会が行われます。No dia 24 de maio de 2012. Centro Evangelístico Internacional. Rua Lemos Cunha 577, Icaraí. Niterói-RJ', 'C', 'brazil_diary_blogger'),
(57, '日系人の定食屋さんへお願いしてきました', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_15.html', '2012-05-15', '児童養護施設', 'こんにちは、エパタです。「日本の児童養護施設設立のための寄付のお願い」ポルトガル語版を30部、今までお願いに行ったことのないお店にお願いしてきました。アラサトゥーバの繁華街「カウサダォン」の中にある定食屋さんです。けっこうおいしくてボリュームがあり、家庭的な味のお店です。私はここの「パステル」が好きです。四角くて大きな春巻きのようなもので、皮生地の中にいろいろな具を入れてもらい、揚げたスナックです。このお店のオーナーさんも日系人で、クリスチャンです。「東京アンテオケ教会」のホームページを紹介しました。主よ、このお店も祝福してくださいますように。。。', 'こんにちは、エパタです。「日本の児童養護施設設立のための寄付のお願い」ポルトガル語版を30部、今までお願いに行ったことのないお店にお願いしてきました。アラサトゥーバの繁華街「カウサダォン」の中にある定食屋さんです。けっこうおいしくてボリュームがあり、家庭的な味のお店です。私はここの「パステル」が好きです。四角くて大きな春巻きのようなもので、皮生地の中にいろいろな具を入れてもらい、揚げたスナックです。このお店のオーナーさんも日系人で、クリスチャンです。「東京アンテオケ教会」のホームページを紹介しました。主よ、このお店も祝福してくださいますように。。。', 'C', 'brazil_diary_blogger'),
(58, 'リオ集会の場所', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_9762.html', '2012-05-15', 'ブラジル日記', 'こんばんは、エパタです。リオデジャネイロの集会のために場所を貸してくださる国際伝道センターはこんな感じです。第七ブラジルチームの時の写真です。あの時は、国際伝道センターの教会員の方々も参加してくださいました。左は賛美の時間。やすらぎの歌を日本語で歌いました。言葉はわからなくても、聖霊様のご臨在を感じて、霊歌で歌って合わせてくださったり、涙を流しておられる方もいました。住所は Rua Lemos Cunha, 577 - Icarai, Niteroi - Rio de Janeiro', 'こんばんは、エパタです。リオデジャネイロの集会のために場所を貸してくださる国際伝道センターはこんな感じです。第七ブラジルチームの時の写真です。あの時は、国際伝道センターの教会員の方々も参加してくださいました。左は賛美の時間。やすらぎの歌を日本語で歌いました。言葉はわからなくても、聖霊様のご臨在を感じて、霊歌で歌って合わせてくださったり、涙を流しておられる方もいました。住所は Rua Lemos Cunha, 577 - Icarai, Niteroi - Rio de Janeiro', 'C', 'brazil_diary_blogger'),
(59, '自宅を出るとどういう接続があるか？', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_17.html', '2012-05-17', 'ブラジルの接続事情', 'いつもは自宅でノートPCで、ルーター接続でブログを書いています。そこで自宅を出たら、どういう接続ができるかと考えました。携帯電話はVIVOという会社のプリペイド式のもので、カードを買ってチャージします。ブラジルの携帯は高いですが、色々工夫しながら接続事情を書いていきます。', 'いつもは自宅でノートPCで、ルーター接続でブログを書いています。そこで自宅を出たら、どういう接続ができるかと考えました。携帯電話はVIVOという会社のプリペイド式のもので、カードを買ってチャージします。ブラジルの携帯は高いですが、色々工夫しながら接続事情を書いていきます。', 'C', 'brazil_diary_blogger'),
(60, 'ネットで買った携帯からツィッターに写真UPできました', 'https://tlccc-mission-bra.blogspot.com/2012/05/up.html', '2012-05-17', 'ブラジル日記', 'ブラジルはまだまだ、話すだけの携帯は安い物ですが、ネット対応は高価です。インターネットで中国製の携帯を購入してみました。Opera mini が入っていて、Wi-Fiがあればツィッターに写真をアップできます。主よ、アンプが飛行機に乗らないそうです！どうすればよいのでしょう？', 'ブラジルはまだまだ、話すだけの携帯は安い物ですが、ネット対応は高価です。インターネットで中国製の携帯を購入してみました。Opera mini が入っていて、Wi-Fiがあればツィッターに写真をアップできます。主よ、アンプが飛行機に乗らないそうです！どうすればよいのでしょう？', 'C', 'brazil_diary_blogger'),
(61, 'ブラジルにいる誰かが見てくれています', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_8116.html', '2012-05-17', 'ブラジル日記', 'すごい！ このブログをブラジルから誰かが見てくれています。UPするとすぐ＋１をくれる、あなた！ どうもありがとう!! Eu fico feliz porque alguém do Brasil está visitando este blog logo depois que eu fiz upload!', 'すごい！ このブログをブラジルから誰かが見てくれています。UPするとすぐ＋１をくれる、あなた！ どうもありがとう!! Eu fico feliz porque alguém do Brasil está visitando este blog logo depois que eu fiz upload!', 'C', 'brazil_diary_blogger'),
(62, 'Saindo da casa... 出発', 'https://tlccc-mission-bra.blogspot.com/2012/05/saindo-da-casa.html', '2012-05-21', 'ブラジル日記', 'Bom dia! Estou saindo da casa agora e vou para Sao Paulo....<br />家を出てサンパウロに向かいます<br /><br />Acho que voy poder escrevendo proximo artigo na cyber cafe....<br />次に更新できるのは、ネットカフェが見つかったらになると思います....<br /><br />Por favor orar para que eu possa fazer a vontade dEle, e voltar em seguro<br />御心を行って無事帰って来れますように、お祈りください<br /><br />Arigatoo!', 'Bom dia! Estou saindo da casa agora e vou para Sao Paulo....
家を出てサンパウロに向かいます

Acho que voy poder escrevendo proximo artigo na cyber cafe....
次に更新できるのは、ネットカフェが見つかったらになると思います....

Por favor orar para que eu possa fazer a vontade dEle, e voltar em seguro
御心を行って無事帰って来れますように、お祈りください

Arigatoo!', 'C', 'brazil_diary_blogger'),
(63, 'サンパウロに到着しました', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_22.html', '2012-05-22', 'ブラジル日記', '今、サンパウロに到着しました。お祈りをありがとうございます。これからグァルーリョスに向かいます。引き続きどうぞお祈りください。', '今、サンパウロに到着しました。お祈りをありがとうございます。これからグァルーリョスに向かいます。引き続きどうぞお祈りください。', 'C', 'brazil_diary_blogger'),
(64, 'hotel ni tootyaku', 'https://tlccc-mission-bra.blogspot.com/2012/05/hotel-ni-tootyaku.html', '2012-05-22', 'ブラジル日記', 'guarulhos san paulo kokusai kuukoo no chikaku no hotel ni tootyaku shimashita. juutai ga sugokatta! kedo kansya shimasu. net cafe desuga, yahari nihongo wa yomemasuga nihongo nyuuryoku site ga block saremasu... oinori o kansya shimasu!', 'guarulhos san paulo kokusai kuukoo no chikaku no hotel ni tootyaku shimashita. juutai ga sugokatta! kedo kansya shimasu. net cafe desuga, yahari nihongo wa yomemasuga nihongo nyuuryoku site ga block saremasu... oinori o kansya shimasu!', 'C', 'brazil_diary_blogger'),
(65, '到着 cheguei em casa...', 'https://tlccc-mission-bra.blogspot.com/2012/05/cheguei-em-casa.html', '2012-05-26', 'ブラジル日記', '無事にアラサトゥーバの自宅へ帰宅しました。お祈りをありがとうございました。<br />Cheguei agora na minha casa em Araçatuba.... Muito obrigada pela sua oração!', '無事にアラサトゥーバの自宅へ帰宅しました。お祈りをありがとうございました。
Cheguei agora na minha casa em Araçatuba.... Muito obrigada pela sua oração!', 'C', 'brazil_diary_blogger'),
(66, 'ブラジルチームの祝福その１～リオデジャネイロの児童支援施設を訪問', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_28.html', '2012-05-28', '児童支援施設', '今回、もっとも強く印象に残っていることは、リオデジャネイロのノボ・テンポ教会のかかわりが開かれたことでした。チームが出発する数日前には「今回はその予定はない」とのことでしたが、出発の時にはスケジュールの中に入っていたのでした。<br /><br />ノボ・テンポ教会はブラジルの貧しい地域の子供たちを支援する団体を設立し、運営しています。この児童支援施設は、麻薬密売人たちが多く住んでいると言われるファベーラ（貧民街）の中にあります。車を降りた時、「ここは危ない」と危機感を覚えました。でも、マルチェロ師は貧しい地域に入っていく伝道をビジョンとして持っておられ、教育の機会を与えることで、犯罪のループを断ち切ろうとされています。本当に感心しました。', '今回、もっとも強く印象に残っていることは、リオデジャネイロのノボ・テンポ教会のかかわりが開かれたことでした。チームが出発する数日前には「今回はその予定はない」とのことでしたが、出発の時にはスケジュールの中に入っていたのでした。

ノボ・テンポ教会はブラジルの貧しい地域の子供たちを支援する団体を設立し、運営しています。この児童支援施設は、麻薬密売人たちが多く住んでいると言われるファベーラ（貧民街）の中にあります。車を降りた時、「ここは危ない」と危機感を覚えました。でも、マルチェロ師は貧しい地域に入っていく伝道をビジョンとして持っておられ、教育の機会を与えることで、犯罪のループを断ち切ろうとされています。本当に感心しました。', 'C', 'brazil_diary_blogger'),
(67, 'ブラジルチームの祝福その２', 'https://tlccc-mission-bra.blogspot.com/2012/05/blog-post_29.html', '2012-05-29', 'ブラジル日記', '最初の日、チームが奉仕した教会は、今まで関わりが開かれたことのない、サン・ジョゼ・ドス・カンポスというサンパウロから西に100キロの都市にある教会でした。イラリオ牧師ご夫妻がチームを空港まで迎えに来てくださいました。大型バンでの移動は非常に快適で、道に迷わずに済み、本当に助かりました。感謝いたします！', '最初の日、チームが奉仕した教会は、今まで関わりが開かれたことのない、サン・ジョゼ・ドス・カンポスというサンパウロから西に100キロの都市にある教会でした。イラリオ牧師ご夫妻がチームを空港まで迎えに来てくださいました。大型バンでの移動は非常に快適で、道に迷わずに済み、本当に助かりました。感謝いたします！', 'C', 'brazil_diary_blogger'),
(68, '10パーセント', 'https://tlccc-mission-bra.blogspot.com/2012/05/10.html', '2012-05-31', '児童養護施設', 'こんにちは、エパタです。前述した有名ホテルへ再び「日本孤児院の設立のための寄付のお願い」を20部持って行きました。オーナーに直接お会いし、真剣に説明しました。「必要な資金の10分の1はもう集まりました」と言うべきところ、言葉に詰まってしまいましたが、「10パーセントね」と助け舟を出してくれました。はっきり具体的なお話をすると、関心を持っていただけるのだなと勉強になりました。', 'こんにちは、エパタです。前述した有名ホテルへ再び「日本孤児院の設立のための寄付のお願い」を20部持って行きました。オーナーに直接お会いし、真剣に説明しました。「必要な資金の10分の1はもう集まりました」と言うべきところ、言葉に詰まってしまいましたが、「10パーセントね」と助け舟を出してくれました。はっきり具体的なお話をすると、関心を持っていただけるのだなと勉強になりました。', 'C', 'brazil_diary_blogger'),
(69, 'ブラジルチームの祝福その３', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post.html', '2012-06-01', 'チーム', '今回、チーム前に特に主にすがって祈っていたことは、通訳の奉仕のこと。ひさしぶりで緊張していましたが、最初のアッセンブリー教会ではポルトガル語に慣れた通訳者を主がすでに備えておられました！その方のポルトガル語訳を聞きながら、私もキリスト教用語のポルトガル語に慣れることができました。本当にご臨在がすばらしく、会衆が熱心に主を求めているのを感じました。', '今回、チーム前に特に主にすがって祈っていたことは、通訳の奉仕のこと。ひさしぶりで緊張していましたが、最初のアッセンブリー教会ではポルトガル語に慣れた通訳者を主がすでに備えておられました！その方のポルトガル語訳を聞きながら、私もキリスト教用語のポルトガル語に慣れることができました。本当にご臨在がすばらしく、会衆が熱心に主を求めているのを感じました。', 'C', 'brazil_diary_blogger'),
(70, 'ブラジルチームの祝福その４～心のふるさとリオデジャネイロ', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_02.html', '2012-06-02', 'リオデジャネイロ', 'また、ひさしぶりにリオデジャネイロに行けたことは一つの恵みでした。リオは私の心の故郷の一つです。国際伝道センターの設立者の牧師が病気から回復されたということで、お見舞いに行きました。少しの時間ですが、リオの街中を歩くことができ、本当に祝福でした。', 'また、ひさしぶりにリオデジャネイロに行けたことは一つの恵みでした。リオは私の心の故郷の一つです。国際伝道センターの設立者の牧師が病気から回復されたということで、お見舞いに行きました。少しの時間ですが、リオの街中を歩くことができ、本当に祝福でした。', 'C', 'brazil_diary_blogger'),
(71, 'ブラジルチームの祝福その５～通訳での主の助け', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_03.html', '2012-06-03', 'ブラジル日記', '集会での最初の通訳。最初、心が動揺してしどろもどろになりそうでしたが、日本チームの方々が熱心に祈ってくださっているのを感じ、少しずつ落ち着くことができました。主が働かれ、素晴らしい証しとなりました。とりなしの祈りの力を深く感じた一時でした。', '集会での最初の通訳。最初、心が動揺してしどろもどろになりそうでしたが、日本チームの方々が熱心に祈ってくださっているのを感じ、少しずつ落ち着くことができました。主が働かれ、素晴らしい証しとなりました。とりなしの祈りの力を深く感じた一時でした。', 'C', 'brazil_diary_blogger'),
(72, 'ブラジルチームの祝福その６～ホザンジェラさん', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_04.html', '2012-06-04', 'チーム', 'ホザンジェラさんは国際伝道センターのミッショナリー。2007年の時に、お父様が心臓発作で緊急治療室に入院された際、チームが癒しのために祈った後、一週間もしないうちに回復し、現在90歳でお元気だそうです。主は生きておられます。ハレルヤ！', 'ホザンジェラさんは国際伝道センターのミッショナリー。2007年の時に、お父様が心臓発作で緊急治療室に入院された際、チームが癒しのために祈った後、一週間もしないうちに回復し、現在90歳でお元気だそうです。主は生きておられます。ハレルヤ！', 'C', 'brazil_diary_blogger'),
(73, 'ブラジルチームの祝福その７～500キロの運転をしてくださった！', 'https://tlccc-mission-bra.blogspot.com/2012/06/400.html', '2012-06-05', 'ブラジル日記', '今回の祝福の一つは、サン・ジョゼ・ドス・カンポスの教会のプロの運転手さんがチームをサンパウロ空港からリオまで送ってくださったことでした。おかげで非常にスムーズに移動でき、大渋滞を回避できました。まさに主の守りです。ありがとうございました！', '今回の祝福の一つは、サン・ジョゼ・ドス・カンポスの教会のプロの運転手さんがチームをサンパウロ空港からリオまで送ってくださったことでした。おかげで非常にスムーズに移動でき、大渋滞を回避できました。まさに主の守りです。ありがとうございました！', 'C', 'brazil_diary_blogger'),
(74, 'ブラジルチームの祝福その８～通訳ってこんなに楽しかったのか！', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_06.html', '2012-06-06', 'チーム', '今回、通訳への恐れがありましたが、この日は自分でも驚くほど自由に話すことができ、「蝶が舞うように」通訳ができました。パウロ師が「神は生きておられます！」と叫んだ瞬間、聖霊様が力強く働かれ、最高に通訳が楽しいと感じた瞬間でした。すべての栄光を主に！', '今回、通訳への恐れがありましたが、この日は自分でも驚くほど自由に話すことができ、「蝶が舞うように」通訳ができました。パウロ師が「神は生きておられます！」と叫んだ瞬間、聖霊様が力強く働かれ、最高に通訳が楽しいと感じた瞬間でした。すべての栄光を主に！', 'C', 'brazil_diary_blogger'),
(75, 'ブラジルチームの祝福その９～シュラスコ !!', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_07.html', '2012-06-07', 'ブラジル日記', 'ブラジルの伝統料理といえば「シュハスコ（バーベキュー）」です！チームの皆さんと美味しいピカーニャ（イチボ肉）をいただきました。アッセンブリー教会の牧師様がごちそうしてくださいました。本当に感謝いたします！', 'ブラジルの伝統料理といえば「シュハスコ（バーベキュー）」です！チームの皆さんと美味しいピカーニャ（イチボ肉）をいただきました。アッセンブリー教会の牧師様がごちそうしてくださいました。本当に感謝いたします！', 'C', 'brazil_diary_blogger'),
(76, 'Agradecimento', 'https://tlccc-mission-bra.blogspot.com/2012/06/agradecimento.html', '2012-06-07', 'ブラジル日記', 'Obrigada por você que está marcando com um +1 ;) sempre logo depois que eu fiz upload... Em breve vou voltar a aprender hebraico de novo! Continue me dando forças, toda raba!!', 'Obrigada por você que está marcando com um +1 ;) sempre logo depois que eu fiz upload... Em breve vou voltar a aprender hebraico de novo! Continue me dando forças, toda raba!!', 'C', 'brazil_diary_blogger'),
(77, 'ブラジルチームの祝福その１０～料金所はだれが？', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_08.html', '2012-06-08', 'ブラジル日記', 'いつもブラジルチームの移動は大変なのですが、今回は料金所を誰がいつ払ったか分からないほどスムーズでした。もしかして、運転手のSr. Luisが支払ってくださったのでしょうか？本当にありがとうございました！', 'いつもブラジルチームの移動は大変なのですが、今回は料金所を誰がいつ払ったか分からないほどスムーズでした。もしかして、運転手のSr. Luisが支払ってくださったのでしょうか？本当にありがとうございました！', 'C', 'brazil_diary_blogger'),
(78, 'ブラジルチームの祝福その11～癒しを求める人の列', 'https://tlccc-mission-bra.blogspot.com/2012/06/11.html', '2012-06-09', 'チーム', 'リオデジャネイロのニテロイ市の国際伝道センターで集会を行いました。ホザンジェラさんのお父様に起こった奇跡の証しを聞いて、多くの方が集まり、集会後には癒しを求めて長い列ができました。チームの皆さんと一緒に、お一人ずつ熱心にお祈りさせていただきました。', 'リオデジャネイロのニテロイ市の国際伝道センターで集会を行いました。ホザンジェラさんのお父様に起こった奇跡の証しを聞いて、多くの方が集まり、集会後には癒しを求めて長い列ができました。チームの皆さんと一緒に、お一人ずつ熱心にお祈りさせていただきました。', 'C', 'brazil_diary_blogger'),
(79, 'ブラジルチームの祝福その12～お二人に助けられました', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_10.html', '2012-06-10', 'ブラジル日記', '今回のチームは、中南米部門のY姉、ヨーロッパ部門のS姉が加わってくださり、ホテルの交渉や手続きを英語で強気に進めてくださいました。おかげで私のポルトガル語の負担もずいぶん減り、本当に楽になりました。素晴らしいパワーに感謝いたします！', '今回のチームは、中南米部門のY姉、ヨーロッパ部門のS姉が加わってくださり、ホテルの交渉や手続きを英語で強気に進めてくださいました。おかげで私のポルトガル語の負担もずいぶん減り、本当に楽になりました。素晴らしいパワーに感謝いたします！', 'C', 'brazil_diary_blogger'),
(80, 'ブラジルチームの祝福その13～すごかったなあの踊り', 'https://tlccc-mission-bra.blogspot.com/2012/06/13.html', '2012-06-11', 'チーム', 'ノボ・テンポ教会のダンス、ものすごい迫力でした！子供たちもカラフルな衣装でダンスを披露してくれました。私も一緒に少し混じって踊りましたが、とても心が解放される素晴らしい一時でした。ダンスを通じて教会へ来る子供たちも多いそうです。', 'ノボ・テンポ教会のダンス、ものすごい迫力でした！子供たちもカラフルな衣装でダンスを披露してくれました。私も一緒に少し混じって踊りましたが、とても心が解放される素晴らしい一時でした。ダンスを通じて教会へ来る子供たちも多いそうです。', 'C', 'brazil_diary_blogger'),
(81, 'ブラジルチームの祝福その14～空港で会えた', 'https://tlccc-mission-bra.blogspot.com/2012/06/14.html', '2012-06-12', 'ブラジル日記', '初対面のイラリオ牧師ご一行と、どうやって空港で合流するか心配でしたが、お互いに名前を書いた紙を持って待つことにしました。フライトの遅れもありましたが、グローボ出版のカウンター前で無事に合流できました。主の完璧な導きにハレルヤ！', '初対面のイラリオ牧師ご一行と、どうやって空港で合流するか心配でしたが、お互いに名前を書いた紙を持って待つことにしました。フライトの遅れもありましたが、グローボ出版のカウンター前で無事に合流できました。主の完璧な導きにハレルヤ！', 'C', 'brazil_diary_blogger'),
(82, 'ブラジルチームの祝福その15～初めての映像の働き！', 'https://tlccc-mission-bra.blogspot.com/2012/06/blog-post_28.html', '2012-06-13', 'ブラジル日記', '今回は初めて映像班が同行し、一連の宣教報告の流れを動画で記録することができました。素晴らしい映像の働きに感謝いたします。YouTubeでもチームの映像が用いられています。', '今回は初めて映像班が同行し、一連の宣教報告の流れを動画で記録することができました。素晴らしい映像の働きに感謝いたします。YouTubeでもチームの映像が用いられています。', 'C', 'brazil_diary_blogger'),
(83, 'リアルタイムとりなし', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_29.html', '2013-10-29', '祈り', 'イスラエル・ヨーロッパチームが日本を出発し、テルアビブに向かっています。乱気流などの困難もありましたが、リアルタイムでのブログ報告と、日本からの多くのとりなしの祈りによって完璧に守られています。主をほめたたえます！', 'イスラエル・ヨーロッパチームが日本を出発し、テルアビブに向かっています。乱気流などの困難もありましたが、リアルタイムでのブログ報告と、日本からの多くのとりなしの祈りによって完璧に守られています。主をほめたたえます！', 'C', 'brazil_diary_blogger'),
(84, 'リアルタイムとりなし・その２', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_2468.html', '2013-10-29', '祈り', 'ルフトハンザ組は無事テルアビブに到着しました。アメリカからのトルコ航空組とも合流し、エルサレムのホテルへ。オーストリア航空組も無事に到着したようです。皆さんの熱心なお祈りに深く感謝いたします！', 'ルフトハンザ組は無事テルアビブに到着しました。アメリカからのトルコ航空組とも合流し、エルサレムのホテルへ。オーストリア航空組も無事に到着したようです。皆さんの熱心なお祈りに深く感謝いたします！', 'C', 'brazil_diary_blogger'),
(85, '祈りの答え', 'https://tlccc-mission-bra.blogspot.com/2015/03/blog-post_47.html', '2015-03-02', 'ブラジル日記', 'Tさんが大腸からの出血とデング熱で入院されました。どうぞすみやかな癒しのためにお祈りください。', 'Tさんが大腸からの出血とデング熱で入院されました。どうぞすみやかな癒しのためにお祈りください。', 'C', 'brazil_diary_blogger'),
(86, 'イスラエルからのアクセスが最多に!?', 'https://tlccc-mission-bra.blogspot.com/2012/11/blog-post_3568.html', '2012-11-14', 'イスラエル', 'こんにちは、エパタです。このブログのアクセス数の地域別のデータで、いつもは1位日本、2位ブラジルとなるのですが、今日のデータでは、なんとイスラエルからのアクセスが最多になってました!! 日本語のブログなのですがどなたが見てくだっているのでしょう？ とても感謝です。', 'こんにちは、エパタです。このブログのアクセス数の地域別のデータで、いつもは1位日本、2位ブラジルとなるのですが、今日のデータでは、なんとイスラエルからのアクセスが最多になってました!! 日本語のブログなのですがどなたが見てくだっているのでしょう？ とても感謝です。', 'C', 'brazil_diary_blogger'),
(87, 'イスラエルが大好きです', 'https://tlccc-mission-bra.blogspot.com/2012/11/blog-post_15.html', '2012-11-15', 'イスラエル', 'こんばんは、エパタです。私はクリスチャンですが、イスラエルに5回行ったことがあり、イスラエルが大好きです。景色がとてもきれいで、雰囲気が良いので、住みたいと思いました。それ以来、ヘブライ語の文字に興味があり、一人で勉強していましたが、今はインターネットでたくさん友達ができて、教えてくれています。', 'こんばんは、エパタです。私はクリスチャンですが、イスラエルに5回行ったことがあり、イスラエルが大好きです。景色がとてもきれいで、雰囲気が良いので、住みたいと思いました。それ以来、ヘブライ語の文字に興味があり、一人で勉強していましたが、今はインターネットでたくさん友達ができて、教えてくれています。', 'C', 'brazil_diary_blogger'),
(88, 'カギが見つかった！', 'https://tlccc-mission-bra.blogspot.com/2012/11/blog-post_8969.html', '2012-11-18', '感謝', '自転車に乗ってスーパーまで買い物に行き、帰ろうとしたら、ポケットに自転車のカギがないことに気づきました。スーパーのレジやお兄さんに聞いても見つからず、途方に暮れました。しかし、「すべての事について感謝しなさい」との御言葉を思い出し、神様に感謝し始めました。すると、心に「カギは家にある」という思いが浮かび、歩いて家に帰ってみると、なんとドアに鍵がささったままでした！泥棒に盗まれず、大家さんにスペアを借りて無事に解決。カギの場所を教えてくださった主に栄光をお返しします！', '自転車に乗ってスーパーまで買い物に行き、帰ろうとしたら、ポケットに自転車のカギがないことに気づきました。スーパーのレジやお兄さんに聞いても見つからず、途方に暮れました。しかし、「すべての事について感謝しなさい」との御言葉を思い出し、神様に感謝し始めました。すると、心に「カギは家にある」という思いが浮かび、歩いて家に帰ってみると、なんとドアに鍵がささったままでした！泥棒に盗まれず、大家さんにスペアを借りて無事に解決。カギの場所を教えてくださった主に栄光をお返しします！', 'C', 'brazil_diary_blogger'),
(89, '母とスカイプで話しました', 'https://tlccc-mission-bra.blogspot.com/2012/11/blog-post_24.html', '2012-11-24', 'ブラジル日記', 'こんばんは、エパタです。昨日は久しぶりに母とスカイプで話すことができました。セキュリティーの問題で、変なメールが来たりしたとのことで、現在は教会のオンライン礼拝の代わりにアーカイブビデオを見てくれています。母が「イスラエルは行ったの？」と話題を出してくれたので、イスラエルチームの席がちょうど62名与えられた話や、チームがイスラエルを去って一週間もしないうちに紛争が起こったことなどの話もすることができました。覚えていてくれて感謝です。', 'こんばんは、エパタです。昨日は久しぶりに母とスカイプで話すことができました。セキュリティーの問題で、変なメールが来たりしたとのことで、現在は教会のオンライン礼拝の代わりにアーカイブビデオを見てくれています。母が「イスラエルは行ったの？」と話題を出してくれたので、イスラエルチームの席がちょうど62名与えられた話や、チームがイスラエルを去って一週間もしないうちに紛争が起こったことなどの話もすることができました。覚えていてくれて感謝です。', 'C', 'brazil_diary_blogger'),
(90, 'クリスマス・プレゼント', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post.html', '2012-12-06', 'ブラジル日記', 'こんばんは、エパタです。今年も市内の孤児院にささやかなクリスマスプレゼントをしたいと考えています。かなり物価が上がっていて、豪勢にはできませんが、プレゼントの包装などもしたいといろいろ見てまわっています。やっぱりプレゼントはもらうより、するほうが楽しいですね！地域の方々にも寄付金を呼びかけていて、寄付を約束してくださった方もいました。さらに御心の額の寄付金が集まり、御心のプレゼントをすることができますように、お祈りください。また、プレゼントが子供たちにとって喜びとなり、祝福となりますように。。。', 'こんばんは、エパタです。今年も市内の孤児院にささやかなクリスマスプレゼントをしたいと考えています。かなり物価が上がっていて、豪勢にはできませんが、プレゼントの包装などもしたいといろいろ見てまわっています。やっぱりプレゼントはもらうより、するほうが楽しいですね！地域の方々にも寄付金を呼びかけていて、寄付を約束してくださった方もいました。さらに御心の額の寄付金が集まり、御心のプレゼントをすることができますように、お祈りください。また、プレゼントが子供たちにとって喜びとなり、祝福となりますように。。。', 'C', 'brazil_diary_blogger'),
(91, 'やすらぎの歌12集が届きました♬', 'https://tlccc-mission-bra.blogspot.com/2012/12/12.html', '2012-12-08', 'ブラジル日記', 'こんにちは、エパタです。昨日、待ちに待った「やすらぎの歌12集」が届きました。早速何度も繰り返して聞いています。ブラジルからも再び作詞・作曲の恵みが与えられますように...。 ', 'こんにちは、エパタです。昨日、待ちに待った「やすらぎの歌12集」が届きました。早速何度も繰り返して聞いています。ブラジルからも再び作詞・作曲の恵みが与えられますように...。', 'C', 'brazil_diary_blogger'),
(92, '牧師の娘さんでした', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_11.html', '2012-12-11', 'ポルトガル語', '近所でよく遊んでいる女の子のお母さんに話しかけ、「日本から来た宣教師ですが、娘さんに日本語を教えてもいいですか？」と聞いてみました。すると、彼女はアッセンブリーの教会の牧師さんの娘さんでした！今はバケーション中ですが、ゲームで遊ぶくらいから始めてみようということになりました。主の素晴らしい導きを感謝します。', '近所でよく遊んでいる女の子のお母さんに話しかけ、「日本から来た宣教師ですが、娘さんに日本語を教えてもいいですか？」と聞いてみました。すると、彼女はアッセンブリーの教会の牧師さんの娘さんでした！今はバケーション中ですが、ゲームで遊ぶくらいから始めてみようということになりました。主の素晴らしい導きを感謝します。', 'C', 'brazil_diary_blogger'),
(93, '日本語クラスの場所', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_12.html', '2012-12-12', 'ブラジル日記', '近所に以前少し話をした主婦の方がいて、ご主人と立ち話をしていると彼女も出てきたので、また少し話をしました。「私は宣教師で無料で日本語を教えます。あなたの家でどうですか？」と単刀直入に聞いてみると、彼女には日系人の友人がたくさんおられるそうで、「聞いてみる」と言ってくださいました。主イエス様の導きを感謝します！', '近所に以前少し話をした主婦の方がいて、ご主人と立ち話をしていると彼女も出てきたので、また少し話をしました。「私は宣教師で無料で日本語を教えます。あなたの家でどうですか？」と単刀直入に聞いてみると、彼女には日系人の友人がたくさんおられるそうで、「聞いてみる」と言ってくださいました。主イエス様の導きを感謝します！', 'C', 'brazil_diary_blogger'),
(94, '手紙を書きました', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_9231.html', '2012-12-12', 'ブラジル日記', '先日、本の整理をしていたら、以前イエス様を受け入れる告白をしたある方の住所を頂き、手紙を書くという約束をしていたのを思い出しました。今日やっと手紙を書き上げました！郵便局はかなり混んでいたので、早急に送れるようにお祈りします。お一人お一人の魂の救いが守られますように。', '先日、本の整理をしていたら、以前イエス様を受け入れる告白をしたある方の住所を頂き、手紙を書くという約束をしていたのを思い出しました。今日やっと手紙を書き上げました！郵便局はかなり混んでいたので、早急に送れるようにお祈りします。お一人お一人の魂の救いが守られますように。', 'C', 'brazil_diary_blogger'),
(95, 'ブックカフェ・アラサトゥーバ☆', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_3503.html', '2012-12-12', '伝道カフェ☆', '街で知り合って、自腹でカフェを開き、伝道用書籍なども販売している方のカフェ「BooKafe」を訪問しました。とても綺麗にやっていました。そこの「私はいやされた」の小冊子を売ってもらうようにお願いしました。カフェがイエス様によって豊かに祝福されますように！<br />Rua General Osório, 494 - Araçatuba-SP', '街で知り合って、自腹でカフェを開き、伝道用書籍なども販売している方のカフェ「BooKafe」を訪問しました。とても綺麗にやっていました。そこの「私はいやされた」の小冊子を売ってもらうようにお願いしました。カフェがイエス様によって豊かに祝福されますように！
Rua General Osório, 494 - Araçatuba-SP', 'C', 'brazil_diary_blogger'),
(96, '「私はいやされた！」が売れました !!', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_15.html', '2012-12-15', '宣伝・広告', '先日訪問して、「私はいやされた！」を4冊売ってくださるようにお願いした伝道所カフェ「BooKafe」にコーヒーを飲みに行きました。すると、オーナーの女性が「置いていった小冊子が一冊売れたわよ！」と。日系人の男性が買って行かれたそうです。主は素晴らしいお仕事をされています！お父様が読まれて主に触れられますように。', '先日訪問して、「私はいやされた！」を4冊売ってくださるようにお願いした伝道所カフェ「BooKafe」にコーヒーを飲みに行きました。すると、オーナーの女性が「置いていった小冊子が一冊売れたわよ！」と。日系人の男性が買って行かれたそうです。主は素晴らしいお仕事をされています！お父様が読まれて主に触れられますように。', 'C', 'brazil_diary_blogger'),
(97, 'いやしの祈りに行ってきました', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_19.html', '2012-12-19', '祈り', '今日はOさんの家にいやしの祈りをさせていただきに行ってきました。Oさんは東京アンテオケ教会の礼拝の言葉に従ったときにイエス様を受け入れられた方で、右手と右足に少し不自由があります。お祈りをしているとき、聖霊様が力強く働いてくださるのを感じ、大きな信仰が湧いてきました。目に見えるところは変わりありませんが、主が素晴らしいお仕事をされているのを感じました。お祈りに覚えていただけると幸いです。', '今日はOさんの家にいやしの祈りをさせていただきに行ってきました。Oさんは東京アンテオケ教会の礼拝の言葉に従ったときにイエス様を受け入れられた方で、右手と右足に少し不自由があります。お祈りをしているとき、聖霊様が力強く働いてくださるのを感じ、大きな信仰が湧いてきました。目に見えるところは変わりありませんが、主が素晴らしいお仕事をされているのを感じました。お祈りに覚えていただけると幸いです。', 'C', 'brazil_diary_blogger'),
(98, '用意万端', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_21.html', '2012-12-21', 'ブラジル日記', 'こんにちは、エパタです。ちょうど安くて良い品物が手に入り、予算より抑えめで用意できました。神様に感謝します。それにしても、どうして女の子たちは、一様にショッキングピンクが好きなのでしょう？ 謎だ....。', 'こんにちは、エパタです。ちょうど安くて良い品物が手に入り、予算より抑えめで用意できました。神様に感謝します。それにしても、どうして女の子たちは、一様にショッキングピンクが好きなのでしょう？ 謎だ....。', 'C', 'brazil_diary_blogger'),
(99, 'ガンの癒しのためにお祈りください', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_23.html', '2012-12-23', '祈り', 'こんばんは、エパタです。昨日は日系人のMさんのお宅を訪問しました。彼女のご主人がサンパウロにお住まいだそうですが、先日消化器系のガンだとわかりました。発見が遅れたため、手術できない状況です。また、治療のために莫大なお金が必要だとわかりました。昨日は二人でイエス様の御名によって祈りました。どうか、癒しのために、また治療費が満たされますように、おとりなしください。', 'こんばんは、エパタです。昨日は日系人のMさんのお宅を訪問しました。彼女のご主人がサンパウロにお住まいだそうですが、先日消化器系のガンだとわかりました。発見が遅れたため、手術できない状況です。また、治療のために莫大なお金が必要だとわかりました。昨日は二人でイエス様の御名によって祈りました。どうか、癒しのために、また治療費が満たされますように、おとりなしください。', 'C', 'brazil_diary_blogger'),
(100, '日本語くらす', 'https://tlccc-mission-bra.blogspot.com/2012/12/blog-post_29.html', '2012-12-29', '日本語クラス', '今日は近所の女の子Aちゃんに日本語を教えに行ってきました。お札の絵や果物のイラストカードを使って「八百屋さんごっこ」をやりました。彼女はコミュニケーションの能力がとても高く、日本語の音に近いポルトガル語を言って楽しんでいました。初めての試みでしたが、彼女と親睦をはかることができ、とても感謝です。毎週日曜日に朝10時から礼拝を持っているので、来てくださいとお誘いすることもできました。', '今日は近所の女の子Aちゃんに日本語を教えに行ってきました。お札の絵や果物のイラストカードを使って「八百屋さんごっこ」をやりました。彼女はコミュニケーションの能力がとても高く、日本語の音に近いポルトガル語を言って楽しんでいました。初めての試みでしたが、彼女と親睦をはかることができ、とても感謝です。毎週日曜日に朝10時から礼拝を持っているので、来てくださいとお誘いすることもできました。', 'C', 'brazil_diary_blogger'),
(101, '日本語くらすの生徒さん？', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post.html', '2013-01-06', 'ブラジル日記', '今日はアラサトゥーバのセントロにお店を出している日系人クリスチャンの方を訪問しました。お孫さんのM君（9歳）に「日本語勉強したらどうですか～」とおばあちゃんにお話すると、「あなた教えてくれる？いくら？」と言われたので、「私は宣教師なのでお代はいただきません」と。お母さんに相談してくださるということで、連絡先を渡しました。どうか楽しく日本語を勉強してくれますように。', '今日はアラサトゥーバのセントロにお店を出している日系人クリスチャンの方を訪問しました。お孫さんのM君（9歳）に「日本語勉強したらどうですか～」とおばあちゃんにお話すると、「あなた教えてくれる？いくら？」と言われたので、「私は宣教師なのでお代はいただきません」と。お母さんに相談してくださるということで、連絡先を渡しました。どうか楽しく日本語を勉強してくれますように。', 'C', 'brazil_diary_blogger'),
(102, '虹', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_6.html', '2013-01-06', 'ブラジル日記', 'バケツをひっくり返したような豪雨のあと、とても薄くですが、虹が....。何が起こるんでしょう⁉ 期待します。アメリカチームの祝福を語っておられるような気がします。(アラサトゥーバにて)', 'バケツをひっくり返したような豪雨のあと、とても薄くですが、虹が....。何が起こるんでしょう⁉ 期待します。アメリカチームの祝福を語っておられるような気がします。(アラサトゥーバにて)', 'C', 'brazil_diary_blogger'),
(103, 'ダビデの町シオン', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_10.html', '2013-01-10', '聖書', '聖書を読んでいたら大きな発見をしました！シオンとは、ダビデの町（列王記一 8:1）だったのです。最初にダビデが占領したエブス人の要害があった場所がシオンの丘で、そこを中心にエルサレムへ発展していったそうです。あの小さな地域がシオンだったのだと知り、感動しました。教えてくださったイエス様に栄光をお返しします！', '聖書を読んでいたら大きな発見をしました！シオンとは、ダビデの町（列王記一 8:1）だったのです。最初にダビデが占領したエブス人の要害があった場所がシオンの丘で、そこを中心にエルサレムへ発展していったそうです。あの小さな地域がシオンだったのだと知り、感動しました。教えてくださったイエス様に栄光をお返しします！', 'C', 'brazil_diary_blogger'),
(104, '英語を教えてほしいと言われました', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_6874.html', '2013-01-10', 'ブラジル日記', '今日、近くの少し高めのスーパーに買い物に行きました。以前日本語を教えてほしいと言われた女の子のレジに並ぶと、彼女から「英語を教えてくれない？」と言われました。どういうわけか、英語を教えることになってしまいましたが、多くの祈りが天に届いた結果かもしれません。主の御心が進みますようにお祈りください。', '今日、近くの少し高めのスーパーに買い物に行きました。以前日本語を教えてほしいと言われた女の子のレジに並ぶと、彼女から「英語を教えてくれない？」と言われました。どういうわけか、英語を教えることになってしまいましたが、多くの祈りが天に届いた結果かもしれません。主の御心が進みますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(105, '家のWi-Fiが使えなくなりました！', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_13.html', '2013-01-13', 'ブラジルの接続事情', '今日は朝から家の固定電話につないでいるルーターが機能せず、Wi-Fiが使えなくなりました。そこで携帯電話の3Gを使って「インターネットを共有」する技を実践してみました。少し遅いですが、ノートPCをつないで無事にブログを更新することができ、非常に重宝しました。クレジットの有効期限などに気をつけながら、これからもネット環境が守られるようお祈りください。', '今日は朝から家の固定電話につないでいるルーターが機能せず、Wi-Fiが使えなくなりました。そこで携帯電話の3Gを使って「インターネットを共有」する技を実践してみました。少し遅いですが、ノートPCをつないで無事にブログを更新することができ、非常に重宝しました。クレジットの有効期限などに気をつけながら、これからもネット環境が守られるようお祈りください。', 'C', 'brazil_diary_blogger'),
(106, 'カルタで神経衰弱', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_8119.html', '2013-01-13', '日本語クラス', '今日はセントロの日系人のお店に行きました。お孫さんのM君（9歳）に日本語を習う許可をもらったので、日本のカルタを使って「神経衰弱」をやりました。その後、イラストを見ながら日本語とポルトガル語で名前の練習をしました。ゲームが終わって確認してみると、日本語の単語をかなり覚えていました。主の導きを感謝します！', '今日はセントロの日系人のお店に行きました。お孫さんのM君（9歳）に日本語を習う許可をもらったので、日本のカルタを使って「神経衰弱」をやりました。その後、イラストを見ながら日本語とポルトガル語で名前の練習をしました。ゲームが終わって確認してみると、日本語の単語をかなり覚えていました。主の導きを感謝します！', 'C', 'brazil_diary_blogger'),
(107, 'ブラジルのチップを日本で購入のアイフォンに！', 'https://tlccc-mission-bra.blogspot.com/2013/01/5.html', '2013-01-14', 'ブラジルの接続事情', 'スマートフォンにVivoのSIMチップを入れて動作確認を行いました。差し込む前に「アクティベート」をしないとSIMを認識しないので注意が必要です。ブラジルの携帯事情やインターネットの速度などを調べながら、効率よく宣教に用いられるよう準備しています。TIM、Claro、Vivoなど各サービスを比較しています。', 'スマートフォンにVivoのSIMチップを入れて動作確認を行いました。差し込む前に「アクティベート」をしないとSIMを認識しないので注意が必要です。ブラジルの携帯事情やインターネットの速度などを調べながら、効率よく宣教に用いられるよう準備しています。TIM、Claro、Vivoなど各サービスを比較しています。', 'C', 'brazil_diary_blogger'),
(108, '電話会社に苦情！', 'https://tlccc-mission-bra.blogspot.com/2013/01/6.html', '2013-01-15', 'ブラジルの接続事情', '大雨のあと、固定電話もインターネットも全く通じなくなりました。携帯からVIVO社のスピーディ担当に電話してもつながらず、やっと見つけたフリーダイヤルに電話して苦情を申し立てました。ブラジルでは「苦情を言う権利」をはっきり主張しないと対応してくれないことが多いと痛感。しばらく不便を楽しんで祈りの対応の訓練とします。', '大雨のあと、固定電話もインターネットも全く通じなくなりました。携帯からVIVO社のスピーディ担当に電話してもつながらず、やっと見つけたフリーダイヤルに電話して苦情を申し立てました。ブラジルでは「苦情を言う権利」をはっきり主張しないと対応してくれないことが多いと痛感。しばらく不便を楽しんで祈りの対応の訓練とします。', 'C', 'brazil_diary_blogger'),
(109, 'オンライン・ライブ中継の仕方', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_16.html', '2013-01-16', 'ブラジル日記', 'PCとUstreamのアカウントさえあれば、オンライン・ライブ中継はどなたでも簡単できます。やり方：Ustreamのアカウントを開ける、カメラとマイクをセットする、「GO LIVE」をクリックする。いつかブラジルの街角インタビュー生中継をやってみたいと、アイデアを祈り求めています。', 'PCとUstreamのアカウントさえあれば、オンライン・ライブ中継はどなたでも簡単できます。やり方：Ustreamのアカウントを開ける、カメラとマイクをセットする、「GO LIVE」をクリックする。いつかブラジルの街角インタビュー生中継をやってみたいと、アイデアを祈り求めています。', 'C', 'brazil_diary_blogger'),
(110, 'つながりました！', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_17.html', '2013-01-17', 'ブラジル日記', 'お祈りをありがとうございます！やっとWi-Fiが復旧しました。ブラジル人との付き合いは長い目で忍耐を持ってやることが必要ですが、時には厚かましくお願いをしてみると通ることも多く、日本より暮らしやすいなと感じる日々です。皆様のとりなしを心から感謝します。', 'お祈りをありがとうございます！やっとWi-Fiが復旧しました。ブラジル人との付き合いは長い目で忍耐を持ってやることが必要ですが、時には厚かましくお願いをしてみると通ることも多く、日本より暮らしやすいなと感じる日々です。皆様のとりなしを心から感謝します。', 'C', 'brazil_diary_blogger'),
(111, '二回目のくらす', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_80.html', '2013-01-17', '日本語クラス', '近所の女の子Aちゃんの家にもう一度日本語を教えに行ってきました。カルタを16枚使ってゲームをやり、いくつかの単語を紹介しました。彼女は「あめ」を「amen」、「かさ」を「caça」、「りんご」を「bingo」など、ポルトガル語の似た言葉と結びつけて覚えていました。最後にお祈りの時を持ちました。主がさらに導いてくださいますように。', '近所の女の子Aちゃんの家にもう一度日本語を教えに行ってきました。カルタを16枚使ってゲームをやり、いくつかの単語を紹介しました。彼女は「あめ」を「amen」、「かさ」を「caça」、「りんご」を「bingo」など、ポルトガル語の似た言葉と結びつけて覚えていました。最後にお祈りの時を持ちました。主がさらに導いてくださいますように。', 'C', 'brazil_diary_blogger'),
(112, '伝道カフェ☆', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_19.html', '2013-01-19', '宣伝・広告', '伝道所カフェ「BooKafe」をまた訪問しました。珍しいアイスコーヒー（6レアル）を見つけて大喜び。働いているスタッフは全員クリスチャンなので、聖書の話やイスラエルに対する立場などの話をポルトガル語でたくさんしました。また「私はいやされた！」の小冊子や「み声新聞」の販売をお願いしてきました。御心の方の手渡されますように！', '伝道所カフェ「BooKafe」をまた訪問しました。珍しいアイスコーヒー（6レアル）を見つけて大喜び。働いているスタッフは全員クリスチャンなので、聖書の話やイスラエルに対する立場などの話をポルトガル語でたくさんしました。また「私はいやされた！」の小冊子や「み声新聞」の販売をお願いしてきました。御心の方の手渡されますように！', 'C', 'brazil_diary_blogger'),
(113, 'おばあちゃんと話しました', 'https://tlccc-mission-bra.blogspot.com/2013/01/m.html', '2013-01-20', 'ブラジル日記', 'M君のおじいちゃんのお店に行ってきました。「日本語くらす」の件をおばあちゃんとお話しました。M君が前回の日本語クラスをとても気に入ってくれて、お母さんに自慢して話してくれたそうです。ハレルヤ！今はバケーション中なので勉強は強要しませんが、お祈りでの助けを本当にありがとうございます。', 'M君のおじいちゃんのお店に行ってきました。「日本語くらす」の件をおばあちゃんとお話しました。M君が前回の日本語クラスをとても気に入ってくれて、お母さんに自慢して話してくれたそうです。ハレルヤ！今はバケーション中なので勉強は強要しませんが、お祈りでの助けを本当にありがとうございます。', 'C', 'brazil_diary_blogger'),
(114, 'スカイプでお祈りしました', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_22.html', '2013-01-22', 'ブラジル日記', 'こんばんは、エパタです。今日はスカイプで、東京におられるSさんとお祈りの時を持つことができました。とても祝福された時となりました。', 'こんばんは、エパタです。今日はスカイプで、東京におられるSさんとお祈りの時を持つことができました。とても祝福された時となりました。', 'C', 'brazil_diary_blogger'),
(115, '「雲の間にある虹」を置いてきました', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_25.html', '2013-01-25', 'ブラジル日記', '伝道所カフェに行って、お茶して、聖書を読み、先日届いたばかりの月刊誌「雲の間にある虹」を2冊、置いていただきました。多くの方に手にとっていただけるようお祈りします。コーヒーとレモンケーキの組み合わせが最高に美味しかった。感謝します。', '伝道所カフェに行って、お茶して、聖書を読み、先日届いたばかりの月刊誌「雲の間にある虹」を2冊、置いていただきました。多くの方に手にとっていただけるようお祈りします。コーヒーとレモンケーキの組み合わせが最高に美味しかった。感謝します。', 'C', 'brazil_diary_blogger'),
(116, 'ブラジル人のメシアニックジューの方と会いました', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_27.html', '2013-01-27', 'イスラエル', '今日、アラサトゥーバのセントロで、ヘブライ語で「救い主イエス」と書かれたTシャツを着たブラジル人メシアニックジューの方と出会いました！以前から「メシアニックジューに会う」との思いが心にあり、お祈りしていました。出会った彼は「また会いますよ」と急いで去って行かれましたが、本当にここにユダヤ人クリスチャンがいるのだと知ることができ、主に心から感謝します！', '今日、アラサトゥーバのセントロで、ヘブライ語で「救い主イエス」と書かれたTシャツを着たブラジル人メシアニックジューの方と出会いました！以前から「メシアニックジューに会う」との思いが心にあり、お祈りしていました。出会った彼は「また会いますよ」と急いで去って行かれましたが、本当にここにユダヤ人クリスチャンがいるのだと知ることができ、主に心から感謝します！', 'C', 'brazil_diary_blogger'),
(117, '「雲の間にある虹」を確認してきました', 'https://tlccc-mission-bra.blogspot.com/2013/01/blog-post_30.html', '2013-01-30', '宣伝・広告', '伝道所カフェに行って、先週置かせていただいた月刊誌「雲の間にある虹」の様子を見てきました。かなり売れているようで嬉しかった。今回はサクラとしてしばらく聖書を読んだあと、写真を撮らせていただきました。こちらのコーヒーとケーキも安くてとても美味しいです。感謝！', '伝道所カフェに行って、先週置かせていただいた月刊誌「雲の間にある虹」の様子を見てきました。かなり売れているようで嬉しかった。今回はサクラとしてしばらく聖書を読んだあと、写真を撮らせていただきました。こちらのコーヒーとケーキも安くてとても美味しいです。感謝！', 'C', 'brazil_diary_blogger'),
(118, '日本語くらす (Aちゃん・その3)', 'https://tlccc-mission-bra.blogspot.com/2013/01/3.html', '2013-01-31', '日本語クラス', '近所の女の子Aちゃんの日本語クラスに行ってきました。今回はひらがなを少し練習し、始めと終わりにお祈りの時を持ちました。Aちゃんはとてもコミュニケーション能力が高く、お祈りの言葉をとてもきれいに繰り返してくれました。初めてのひらがなでしたが、とても上手に書けていました。次回も楽しみにしています！', '近所の女の子Aちゃんの日本語クラスに行ってきました。今回はひらがなを少し練習し、始めと終わりにお祈りの時を持ちました。Aちゃんはとてもコミュニケーション能力が高く、お祈りの言葉をとてもきれいに繰り返してくれました。初めてのひらがなでしたが、とても上手に書けていました。次回も楽しみにしています！', 'C', 'brazil_diary_blogger'),
(119, 'Mさんと一緒に祈りました', 'https://tlccc-mission-bra.blogspot.com/2013/02/m.html', '2013-02-07', 'ブラジル日記', '今日は日系人のMさんを訪問しました。大切な書類の日本語の文字を書く作業をお手伝いし、大変喜ばれました。Mさんのご主人は大腸がんで入院中なので、お二人でイエス・キリストの御名によって、早く治って退院できるようにお祈りしました。主の癒しの御手が置かれますように。', '今日は日系人のMさんを訪問しました。大切な書類の日本語の文字を書く作業をお手伝いし、大変喜ばれました。Mさんのご主人は大腸がんで入院中なので、お二人でイエス・キリストの御名によって、早く治って退院できるようにお祈りしました。主の癒しの御手が置かれますように。', 'C', 'brazil_diary_blogger'),
(120, 'ブラジルのおまわりさん', 'https://tlccc-mission-bra.blogspot.com/2013/02/blog-post.html', '2013-02-14', 'ブラジル日記', '土曜日にセントロに見回りに出かけると、警察の詰所の前で出会うおまわりさんがいます。彼はとても親切で、不審な人がいたときもすっと寄って守ってくれました。ある日はレストランでばったり出会い、お昼をごちそうしてくださいました。本当に素晴らしい出会いに感謝します！', '土曜日にセントロに見回りに出かけると、警察の詰所の前で出会うおまわりさんがいます。彼はとても親切で、不審な人がいたときもすっと寄って守ってくれました。ある日はレストランでばったり出会い、お昼をごちそうしてくださいました。本当に素晴らしい出会いに感謝します！', 'C', 'brazil_diary_blogger'),
(121, 'ゴスペルを歌う人に会いました', 'https://tlccc-mission-bra.blogspot.com/2013/02/blog-post_16.html', '2013-02-16', 'ゴスペル', '繁華街を歩いていると、ゴスペル歌手の女性に声をかけられました。彼女のCDを購入し、「毎週土曜日にここで歌っているから、一緒に歌いましょう」とお誘いしました。ハレルヤ！主の素晴らしいお仕事を感謝します。彼女の曲を一曲練習してみました。お祈りください。', '繁華街を歩いていると、ゴスペル歌手の女性に声をかけられました。彼女のCDを購入し、「毎週土曜日にここで歌っているから、一緒に歌いましょう」とお誘いしました。ハレルヤ！主の素晴らしいお仕事を感謝します。彼女の曲を一曲練習してみました。お祈りください。', 'C', 'brazil_diary_blogger'),
(122, '日本語くらす（M君・その２）', 'https://tlccc-mission-bra.blogspot.com/2013/02/m_17.html', '2013-02-17', '日本語クラス', 'バケーション明け、M君の日本語クラスを再開しました。今回は「お店屋さんごっこ」を行い、いくつかの新しい日本語の単語を覚えました。おじいちゃんおばあちゃんに見守られながら、少し緊張気味でしたが、しっかり「もも」などを覚えていました。主の導きを感謝します。', 'バケーション明け、M君の日本語クラスを再開しました。今回は「お店屋さんごっこ」を行い、いくつかの新しい日本語の単語を覚えました。おじいちゃんおばあちゃんに見守られながら、少し緊張気味でしたが、しっかり「もも」などを覚えていました。主の導きを感謝します。', 'C', 'brazil_diary_blogger'),
(123, 'イエス様が教えてくださっている事', 'https://tlccc-mission-bra.blogspot.com/2013/02/blog-post_18.html', '2013-02-18', '聖書', 'アラム語について、イエス様から新しい気づきをいただいています。映画「パッション」でイエス様がアラム語を話しておられたのがきっかけで調べていました。アラム語はかつて国際共通語として広く用いられており、イエス様も民衆に届くアラム語を宣教のために使われていたのだと思います。状況に合わせて語られる主に感謝します。', 'アラム語について、イエス様から新しい気づきをいただいています。映画「パッション」でイエス様がアラム語を話しておられたのがきっかけで調べていました。アラム語はかつて国際共通語として広く用いられており、イエス様も民衆に届くアラム語を宣教のために使われていたのだと思います。状況に合わせて語られる主に感謝します。', 'C', 'brazil_diary_blogger'),
(124, '日本語くらす（M君・その３）', 'https://tlccc-mission-bra.blogspot.com/2013/02/m_24.html', '2013-02-24', '日本語クラス', 'M君のクラスを行いました。「あめ」「いす」など８個のカルタを使ってお店屋さんごっこと神経衰弱を行いました。カルタの順番や音をしっかり覚えており、神経衰弱はM君の勝ち。もっと楽しいゲームのアイデアが与えられますようにお祈りしています。', 'M君のクラスを行いました。「あめ」「いす」など８個のカルタを使ってお店屋さんごっこと神経衰弱を行いました。カルタの順番や音をしっかり覚えており、神経衰弱はM君の勝ち。もっと楽しいゲームのアイデアが与えられますようにお祈りしています。', 'C', 'brazil_diary_blogger'),
(125, 'メシアニックジューの教会の方に会いました', 'https://tlccc-mission-bra.blogspot.com/2013/02/blog-post_28.html', '2013-02-28', 'イスラエル', 'アラサトゥーバにもユダヤ教のクリスチャンがいるかもしれないと思い、ネットで検索し、それらしき集会所へ自転車で向かいました。途中で熱中症のようになり、近所の薬局のお兄さんにビスケットをいただき無事に回復。近所の方に聞いて集会所にたどり着き、ご家族とお会いして、お話しすることができました。主の御心が進みますようにお祈りください。', 'アラサトゥーバにもユダヤ教のクリスチャンがいるかもしれないと思い、ネットで検索し、それらしき集会所へ自転車で向かいました。途中で熱中症のようになり、近所の薬局のお兄さんにビスケットをいただき無事に回復。近所の方に聞いて集会所にたどり着き、ご家族とお会いして、お話しすることができました。主の御心が進みますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(126, 'ブラジルのメシアニックジューの団体', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_1.html', '2013-03-01', 'ブラジル日記', 'ネットで検索したところ、ブラジルには大きなメシアニックジューのネットワークがあることがわかりました。「イスラエルは時がくれば救われる」「聖霊の賜物を信じる」など、私のビジョンと共通する部分が多く、とても励まされました。主の計画を感謝します！', 'ネットで検索したところ、ブラジルには大きなメシアニックジューのネットワークがあることがわかりました。「イスラエルは時がくれば救われる」「聖霊の賜物を信じる」など、私のビジョンと共通する部分が多く、とても励まされました。主の計画を感謝します！', 'C', 'brazil_diary_blogger'),
(127, '日本語くらす（M君・その4）', 'https://tlccc-mission-bra.blogspot.com/2013/03/m4.html', '2013-03-03', 'ブラジル日記', 'M君の日本語クラスを行いました。おばあちゃんから「勉強しているところを写真に撮りたい」と言われ、少し照れながら行いました。今回から新しく「ねこ」「くま」の2つの単語を追加し、合計10個になりました。お遊びの神経衰弱はM君の圧勝。1から10までの数え方もスラスラ言えていました。主に栄光！', 'M君の日本語クラスを行いました。おばあちゃんから「勉強しているところを写真に撮りたい」と言われ、少し照れながら行いました。今回から新しく「ねこ」「くま」の2つの単語を追加し、合計10個になりました。お遊びの神経衰弱はM君の圧勝。1から10までの数え方もスラスラ言えていました。主に栄光！', 'C', 'brazil_diary_blogger'),
(128, 'ブラジルの接続事情・その7', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post.html', '2013-03-07', 'ブラジル日記', 'スマートフォンの3G接続をTIMチップを使って行っています。一日1レアルで使えて非常に重宝しています。今回は以前から気になっていたIT産業の盛んな都市「ベロオリゾンテ」について少し書きました。主の宣教の門が大きく開かれますようにお祈りください。', 'スマートフォンの3G接続をTIMチップを使って行っています。一日1レアルで使えて非常に重宝しています。今回は以前から気になっていたIT産業の盛んな都市「ベロオリゾンテ」について少し書きました。主の宣教の門が大きく開かれますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(129, 'ブラジルの接続事情・その8', 'https://tlccc-mission-bra.blogspot.com/2013/03/8.html', '2013-03-08', 'ブラジル日記', 'ブラジルの携帯や電磁波について調べ、イヤホンマイクなどの使用が効果的であることを知りました。治安の悪い田舎町では、やはり携帯電話は非常に重要な安全の道具です。正しい知識を使いながら、安全に宣教の働きを続けていきたいと思います。主に期待します！', 'ブラジルの携帯や電磁波について調べ、イヤホンマイクなどの使用が効果的であることを知りました。治安の悪い田舎町では、やはり携帯電話は非常に重要な安全の道具です。正しい知識を使いながら、安全に宣教の働きを続けていきたいと思います。主に期待します！', 'C', 'brazil_diary_blogger'),
(130, '日本語くらす（M君・その5）', 'https://tlccc-mission-bra.blogspot.com/2013/03/m5.html', '2013-03-10', 'ブラジル日記', 'M君のクラス。彼から「lerva（毛虫）」というポルトガル語を教えてもらい、お互いの語学の勉強に。今回は新しく「わに」「うさぎ」など６つの単語を追加して合計14個になりました。カードを使った神経衰弱は9対5で負けてしまいましたが、M君のやる気に感謝します。次回は勝ちます！', 'M君のクラス。彼から「lerva（毛虫）」というポルトガル語を教えてもらい、お互いの語学の勉強に。今回は新しく「わに」「うさぎ」など６つの単語を追加して合計14個になりました。カードを使った神経衰弱は9対5で負けてしまいましたが、M君のやる気に感謝します。次回は勝ちます！', 'C', 'brazil_diary_blogger'),
(131, '電話しました', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_12.html', '2013-03-12', 'ブラジル日記', '英語を教えてほしいと言われた女の子Tさんに電話しました。しばらく勉強する都合がつかないということで、もう少し様子を見ることに。彼女を英語の映画（レ・ミゼラブル）にお誘いし、教会へもお誘いすることができました。主の素晴らしい導きを感謝します。', '英語を教えてほしいと言われた女の子Tさんに電話しました。しばらく勉強する都合がつかないということで、もう少し様子を見ることに。彼女を英語の映画（レ・ミゼラブル）にお誘いし、教会へもお誘いすることができました。主の素晴らしい導きを感謝します。', 'C', 'brazil_diary_blogger'),
(132, '伝道所カフェに行ってきました', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_13.html', '2013-03-13', '伝道カフェ☆', 'Aちゃんの家はお泊まりでお留守でした。映画「レ・ミゼラブル」を一緒に見てくれる人を探していますが、こちらの友達に３人断られてしまいました。伝道所カフェのオーナーさんにお願いして、掲示板に「一緒に行ってくれる方」の募集メモを貼っていただきました。主の導きを感謝します！', 'Aちゃんの家はお泊まりでお留守でした。映画「レ・ミゼラブル」を一緒に見てくれる人を探していますが、こちらの友達に３人断られてしまいました。伝道所カフェのオーナーさんにお願いして、掲示板に「一緒に行ってくれる方」の募集メモを貼っていただきました。主の導きを感謝します！', 'C', 'brazil_diary_blogger'),
(133, 'いやしの祈りに行ってきました', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_16.html', '2013-03-16', '祈り', 'Oさんの家に行って、いやしの祈りをさせていただきました。なるべくポルトガル語で祈り、心が通じるようにお祈りしました。Oさんもご自身で治りたいという意思を強く示すようになってきて、主の素晴らしいお仕事を感じます。さらにいやされるようお祈りください。', 'Oさんの家に行って、いやしの祈りをさせていただきました。なるべくポルトガル語で祈り、心が通じるようにお祈りしました。Oさんもご自身で治りたいという意思を強く示すようになってきて、主の素晴らしいお仕事を感じます。さらにいやされるようお祈りください。', 'C', 'brazil_diary_blogger'),
(134, 'びっくりした事', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_19.html', '2013-03-19', 'ブラジル日記', '夜明けごろ、屋根裏でドーンという大きな音がし、水道の水が天井から降ってきました。大雨が降っているようで、慌てて大家さんと水道会社に連絡。近所のAちゃんのおじいさんが、はしごを持ってきて屋根裏を調べてくれました。水槽が古くなって傾いていたのが原因でした。近所の方々の優しさを深く実感し、主に感謝します！', '夜明けごろ、屋根裏でドーンという大きな音がし、水道の水が天井から降ってきました。大雨が降っているようで、慌てて大家さんと水道会社に連絡。近所のAちゃんのおじいさんが、はしごを持ってきて屋根裏を調べてくれました。水槽が古くなって傾いていたのが原因でした。近所の方々の優しさを深く実感し、主に感謝します！', 'C', 'brazil_diary_blogger'),
(135, '日本語くらす（M君・その6）', 'https://tlccc-mission-bra.blogspot.com/2013/03/m6.html', '2013-03-24', '日本語クラス', 'M君のクラス。今回は新しく「こ」「か」のひらがなの書き方を練習しました。その後はいつものお店屋さんごっこと神経衰弱。今回はかなり本気でやりましたが、１戦目は4対6、２戦目は同点でした。M君がとても楽しそうに目を輝かせてやっているので、それを見れるだけでも主に感謝です！', 'M君のクラス。今回は新しく「こ」「か」のひらがなの書き方を練習しました。その後はいつものお店屋さんごっこと神経衰弱。今回はかなり本気でやりましたが、１戦目は4対6、２戦目は同点でした。M君がとても楽しそうに目を輝かせてやっているので、それを見れるだけでも主に感謝です！', 'C', 'brazil_diary_blogger'),
(136, 'メシアニックジューの方にインタビューしました', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_27.html', '2013-03-27', 'イスラエル', '過ぎ越しの祭り（ペサハ）、おめでとうございます！いつもの伝道所カフェで、ユダヤ人のイェフダさんにお会いしてインタビューをさせていただきました。彼の家庭では毎晩過ぎ越しの記念礼拝が行われているそうです。素晴らしい機会を主に感謝します！', '過ぎ越しの祭り（ペサハ）、おめでとうございます！いつもの伝道所カフェで、ユダヤ人のイェフダさんにお会いしてインタビューをさせていただきました。彼の家庭では毎晩過ぎ越しの記念礼拝が行われているそうです。素晴らしい機会を主に感謝します！', 'C', 'brazil_diary_blogger'),
(137, '直りました', 'https://tlccc-mission-bra.blogspot.com/2013/03/blog-post_30.html', '2013-03-30', 'ブラジル日記', 'こんばんは、エパタです。ご心配おかけしました。水道設備が直りました。お祈りをありがとうございました。', 'こんばんは、エパタです。ご心配おかけしました。水道設備が直りました。お祈りをありがとうございました。', 'C', 'brazil_diary_blogger'),
(138, '日本語くらす（M君・その7）', 'https://tlccc-mission-bra.blogspot.com/2013/03/m7.html', '2013-03-31', '日本語クラス', 'M君のクラス。今回は50音の説明をしました。日本語は「aiueo」であると教えると、アルファベットとの違いに驚いていました。ひらがなをいくつか発音してもらうと、「つ」の音もスラスラ言えていました。最後の神経衰弱はM君の勝ち。お代としてたくさんの元気をいただきました。感謝！', 'M君のクラス。今回は50音の説明をしました。日本語は「aiueo」であると教えると、アルファベットとの違いに驚いていました。ひらがなをいくつか発音してもらうと、「つ」の音もスラスラ言えていました。最後の神経衰弱はM君の勝ち。お代としてたくさんの元気をいただきました。感謝！', 'C', 'brazil_diary_blogger'),
(139, 'またまた発見した事', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post.html', '2013-04-03', '聖書', 'エゼキエル書に出てくるゴグ・マゴグについて調べています。イスラエルを攻める連合軍の一部が、かつてスペインを築いたトバルの一族であるとの記述を見つけ、中南米（ポルトガル語・スペイン語圏）で宣教していることの特別な意味を深く感じました。主の緻密な計画に感謝し、すべての栄光を主に！', 'エゼキエル書に出てくるゴグ・マゴグについて調べています。イスラエルを攻める連合軍の一部が、かつてスペインを築いたトバルの一族であるとの記述を見つけ、中南米（ポルトガル語・スペイン語圏）で宣教していることの特別な意味を深く感じました。主の緻密な計画に感謝し、すべての栄光を主に！', 'C', 'brazil_diary_blogger'),
(140, '電話番号をもらいました', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post_5.html', '2013-04-05', '宣教活動', '今日は大家さんとショッピングセンターに出かけました。靴下売り場の日系人の店員さんに話しかけ、「私は宣教師です」と自己紹介し、会話の練習のために連絡先を聞いたところ、快く教えていただきました。彼女が救われますよう、また礼拝にお誘いできるようにお祈りください。', '今日は大家さんとショッピングセンターに出かけました。靴下売り場の日系人の店員さんに話しかけ、「私は宣教師です」と自己紹介し、会話の練習のために連絡先を聞いたところ、快く教えていただきました。彼女が救われますよう、また礼拝にお誘いできるようにお祈りください。', 'C', 'brazil_diary_blogger'),
(141, '日本語くらす（M君・その8）', 'https://tlccc-mission-bra.blogspot.com/2013/04/m8.html', '2013-04-07', '日本語クラス', 'M君の日本語クラスを行いました。「し」「さ」の練習をし、神経衰弱をしました。M君に「イエスを信じてる？」と聞くと、はっきり「うん」と。「毎日お祈りするよ。学校が安全で、みんなが仲良くお勉強できるように」と教えてくれました。素晴らしい信仰を主に感謝します！', 'M君の日本語クラスを行いました。「し」「さ」の練習をし、神経衰弱をしました。M君に「イエスを信じてる？」と聞くと、はっきり「うん」と。「毎日お祈りするよ。学校が安全で、みんなが仲良くお勉強できるように」と教えてくれました。素晴らしい信仰を主に感謝します！', 'C', 'brazil_diary_blogger'),
(142, 'お昼ご飯をごちそうになりました', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post_11.html', '2013-04-11', 'ブラジル日記', '北京ホテルの劉長生さん、大家さんの前川碧さんと一緒にお昼ご飯をごちそうになりました。劉さんは戦時中、日本軍の通訳として四国の方々と働いておられました。児童養護施設の購入報告をしたところ、とても喜んでくださり、さらなる支援を約束してくださいました。心から感謝いたします！', '北京ホテルの劉長生さん、大家さんの前川碧さんと一緒にお昼ご飯をごちそうになりました。劉さんは戦時中、日本軍の通訳として四国の方々と働いておられました。児童養護施設の購入報告をしたところ、とても喜んでくださり、さらなる支援を約束してくださいました。心から感謝いたします！', 'C', 'brazil_diary_blogger'),
(143, 'ラトビアからも !!', 'https://tlccc-mission-bra.blogspot.com/2013/04/fwd_13.html', '2013-04-13', 'ブラジル日記', 'こんにちは、エパタです。なんとラトビアからのアクセスが、日本からに次いで2番目に多くなっています‼ラトビアから見てくださっている方々、ありがとうございます‼日本語が読めるのですね⁈', 'こんにちは、エパタです。なんとラトビアからのアクセスが、日本からに次いで2番目に多くなっています‼ラトビアから見てくださっている方々、ありがとうございます‼日本語が読めるのですね⁈', 'C', 'brazil_diary_blogger'),
(144, '日本語くらす（M君・その9）', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post_14.html', '2013-04-14', '日本語クラス', 'M君の日本語クラス。今回はひらがな「く」「て」の練習をしました。50音表のなかで、M君がすでに知っている文字に丸をつけてもらいました。かなりひらがなが読めるようになってきていて嬉しい。テキストの「数」の勉強も行い、彼が色塗りをとても楽しんでくれていました。感謝！', 'M君の日本語クラス。今回はひらがな「く」「て」の練習をしました。50音表のなかで、M君がすでに知っている文字に丸をつけてもらいました。かなりひらがなが読めるようになってきていて嬉しい。テキストの「数」の勉強も行い、彼が色塗りをとても楽しんでくれていました。感謝！', 'C', 'brazil_diary_blogger'),
(145, 'Happy Independent Day to Israel!!', 'https://tlccc-mission-bra.blogspot.com/2013/04/happy-independent-day-to-israel.html', '2013-04-17', 'イスラエル', '今日はイスラエルの独立記念日（Yom Ha''atzmaut）です！ヘブライ語の響きが、なぜか私の苗字「まつもと」に聞こえて仕方がありません（笑）。クリスチャンになり、神様に愛されていることを知って自分自身が好きになりました。イスラエル独立を心からお祝いします！', '今日はイスラエルの独立記念日（Yom Ha''atzmaut）です！ヘブライ語の響きが、なぜか私の苗字「まつもと」に聞こえて仕方がありません（笑）。クリスチャンになり、神様に愛されていることを知って自分自身が好きになりました。イスラエル独立を心からお祝いします！', 'C', 'brazil_diary_blogger'),
(146, '「雲の間にある虹」の新刊を出してきました', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post_20.html', '2013-04-20', '宣伝・広告', '私が執筆した月刊「雲の間にある虹5月号」が届きました。いつも置いていただいている伝道所カフェ「BooKafe」にお願いしてきました。ケーキとコーヒーをいただきながら、ディスプレイをさせていただきました。多くの方に読まれますようにお祈りください。', '私が執筆した月刊「雲の間にある虹5月号」が届きました。いつも置いていただいている伝道所カフェ「BooKafe」にお願いしてきました。ケーキとコーヒーをいただきながら、ディスプレイをさせていただきました。多くの方に読まれますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(147, '日本語くらす（M君・その10）', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post_21.html', '2013-04-21', '日本語クラス', 'M君の日本語クラス。お祈りをして始めました。「You are my God」の歌を日本語と英語で歌いましたが、M君は英語の部分を一緒に歌おうとしていて、やはり英語が好きな様子。時計のおもちゃを使って時間（～じ）の言い方を練習しました。神経衰弱は20セットで対決し、大敗しました（笑）。', 'M君の日本語クラス。お祈りをして始めました。「You are my God」の歌を日本語と英語で歌いましたが、M君は英語の部分を一緒に歌おうとしていて、やはり英語が好きな様子。時計のおもちゃを使って時間（～じ）の言い方を練習しました。神経衰弱は20セットで対決し、大敗しました（笑）。', 'C', 'brazil_diary_blogger'),
(148, '祈りが聞かれた！', 'https://tlccc-mission-bra.blogspot.com/2013/04/blog-post_27.html', '2013-04-27', '祈り', '母とスカイプで話しました。母の先週の祈りの課題は、私の弟（町内会リサイクルの責任者）の仕事の負担が減り、町内会全体の仕事になりますように、というものでした。するとお祈りした通りに、リサイクル業者の都合などで期限が延び、弟の負担が劇的に少なくなりました！神様をほめたたえます！', '母とスカイプで話しました。母の先週の祈りの課題は、私の弟（町内会リサイクルの責任者）の仕事の負担が減り、町内会全体の仕事になりますように、というものでした。するとお祈りした通りに、リサイクル業者の都合などで期限が延び、弟の負担が劇的に少なくなりました！神様をほめたたえます！', 'C', 'brazil_diary_blogger'),
(149, '日本語くらす（M君・その11）', 'https://tlccc-mission-bra.blogspot.com/2013/04/m11.html', '2013-04-28', '日本語クラス', '今週も日本語くらすを行いました。最初にお祈りをしてから、お店屋さんごっこと、12セットの神経衰弱。そしてひらがなの「と」「け」の書き方の練習をしました。歌の歌詞に出てくるひらがなに丸をつけてもらいましたが、似た文字の区別を説明する良い機会となりました。主の助けを感謝します！', '今週も日本語くらすを行いました。最初にお祈りをしてから、お店屋さんごっこと、12セットの神経衰弱。そしてひらがなの「と」「け」の書き方の練習をしました。歌の歌詞に出てくるひらがなに丸をつけてもらいましたが、似た文字の区別を説明する良い機会となりました。主の助けを感謝します！', 'C', 'brazil_diary_blogger'),
(150, '日本語くらす（M君・その12）', 'https://tlccc-mission-bra.blogspot.com/2013/05/m12.html', '2013-05-05', '日本語クラス', 'M君の日本語クラス。お祈りをしてから、ひらがな「お」「き」の練習。そして「You are my God」の英語の歌詞をポルトガル語で説明していきました。M君は「きぼうのひかり」を「Que Boa（洗剤メーカー）」とジョークを言って楽しんでいました。素晴らしい集中力で、お遊びなしでやり切れました！', 'M君の日本語クラス。お祈りをしてから、ひらがな「お」「き」の練習。そして「You are my God」の英語の歌詞をポルトガル語で説明していきました。M君は「きぼうのひかり」を「Que Boa（洗剤メーカー）」とジョークを言って楽しんでいました。素晴らしい集中力で、お遊びなしでやり切れました！', 'C', 'brazil_diary_blogger'),
(151, 'ブラジルの接続事情・その9～3Gが使えた', 'https://tlccc-mission-bra.blogspot.com/2013/05/9.html', '2013-05-07', 'グァララペス', '以前住んでいた田舎町グァララペスに行ってきました。道中、バスの窓から広大な草原を眺めながら、スマートフォンの3G接続を試したところ、定額でしっかりとつながりました。写真のアップやブログの更新も高速道路を走りながら無事にできました。TIM社を使いながら、接続環境を調べています。', '以前住んでいた田舎町グァララペスに行ってきました。道中、バスの窓から広大な草原を眺めながら、スマートフォンの3G接続を試したところ、定額でしっかりとつながりました。写真のアップやブログの更新も高速道路を走りながら無事にできました。TIM社を使いながら、接続環境を調べています。', 'C', 'brazil_diary_blogger'),
(152, 'グァララペス訪問のビデオ', 'https://tlccc-mission-bra.blogspot.com/2013/05/blog-post_9.html', '2013-05-09', 'グァララペス', 'スマートフォンのビデオを使って初めて動画編集を試みました。CuteCutというアプリを使って、切ったり貼ったりしてグァララペスの風景を編集しました。途中でアレルギーが出てしまい早々に退散しましたが、動画が伝道のために用いられますようにお祈りください。', 'スマートフォンのビデオを使って初めて動画編集を試みました。CuteCutというアプリを使って、切ったり貼ったりしてグァララペスの風景を編集しました。途中でアレルギーが出てしまい早々に退散しましたが、動画が伝道のために用いられますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(153, 'ブラジルの法律その1- ウズカピアォン', 'https://tlccc-mission-bra.blogspot.com/2013/05/1.html', '2013-05-17', 'ブラジルの法律', 'ブラジルの「ウズカピアォン（所得時効）」という法律について少し書きました。これは、他人の土地に勝手に住み込み、一定期間だれも文句を言わなければ、その人の所有権を認めてしまうという日本人には信じられない法律です。土地の適切な管理や対応について、しっかりと知っておく必要があります。', 'ブラジルの「ウズカピアォン（所得時効）」という法律について少し書きました。これは、他人の土地に勝手に住み込み、一定期間だれも文句を言わなければ、その人の所有権を認めてしまうという日本人には信じられない法律です。土地の適切な管理や対応について、しっかりと知っておく必要があります。', 'C', 'brazil_diary_blogger'),
(154, '日本語くらす（M君・その13）', 'https://tlccc-mission-bra.blogspot.com/2013/05/m13.html', '2013-05-19', '日本語クラス', 'M君のクラス。ひらがな「る」「ろ」を練習しました。「数字の3みたいだね～」と二人で大笑い。神経衰弱は15セット行い、6対9で負けてしまいましたが、M君がとても熱中していて嬉しかった。「You are my God」をmp3で聴きながら、英語の部分を一緒に歌う練習をしました。お祈りで終了しました。', 'M君のクラス。ひらがな「る」「ろ」を練習しました。「数字の3みたいだね～」と二人で大笑い。神経衰弱は15セット行い、6対9で負けてしまいましたが、M君がとても熱中していて嬉しかった。「You are my God」をmp3で聴きながら、英語の部分を一緒に歌う練習をしました。お祈りで終了しました。', 'C', 'brazil_diary_blogger'),
(155, 'ポルトガル語訳をお渡ししました', 'https://tlccc-mission-bra.blogspot.com/2013/05/blog-post.html', '2013-05-23', 'イスラエル', 'サンパウロから戻られたイェフダさんを訪問し、彼について執筆させていただいた「雲の間にある虹5月号」とポルトガル語訳をプレゼントしました。大変喜んでくださり、メシアニック・ジューのブラジル全国会合のリーダーにお見せすると言ってくださいました。主の御名が崇められますように！', 'サンパウロから戻られたイェフダさんを訪問し、彼について執筆させていただいた「雲の間にある虹5月号」とポルトガル語訳をプレゼントしました。大変喜んでくださり、メシアニック・ジューのブラジル全国会合のリーダーにお見せすると言ってくださいました。主の御名が崇められますように！', 'C', 'brazil_diary_blogger'),
(156, '母の腰の痛みがやわらいだ', 'https://tlccc-mission-bra.blogspot.com/2013/05/blog-post_31.html', '2013-05-31', '祈り', '母とスカイプで話しました。1つは、母の腰痛のために先週からお祈りを始めたのですが、今週は全く痛みを感じずに過ごすことができたそうです。2つ目は、甥っ子たちの学校が合併して遠くなった件。良いお友達ができるように祈っていましたが、新しい住人が越してきて楽しく通えているそうです。ハレルヤ！', '母とスカイプで話しました。1つは、母の腰痛のために先週からお祈りを始めたのですが、今週は全く痛みを感じずに過ごすことができたそうです。2つ目は、甥っ子たちの学校が合併して遠くなった件。良いお友達ができるように祈っていましたが、新しい住人が越してきて楽しく通えているそうです。ハレルヤ！', 'C', 'brazil_diary_blogger'),
(157, '日本語くらす（M君・厚生14）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m14.html', '2013-06-02', '日本語クラス', 'M君のクラス。お祈りをして始めて、ひらがな「に」「の」を練習しました。「You are my God」の歌を目で追ってもらいながら、ひらがなを読む練習。神経衰弱は16セットで全力で対決し、みごと同点に持ち込みました！お遊びに熱中しすぎてお祈りを忘れてしまいました（笑）。', 'M君のクラス。お祈りをして始めて、ひらがな「に」「の」を練習しました。「You are my God」の歌を目で追ってもらいながら、ひらがなを読む練習。神経衰弱は16セットで全力で対決し、みごと同点に持ち込みました！お遊びに熱中しすぎてお祈りを忘れてしまいました（笑）。', 'C', 'brazil_diary_blogger'),
(158, 'リオデジャネイロの思い出（その1）', 'https://tlccc-mission-bra.blogspot.com/2013/06/1.html', '2013-06-05', 'リオデジャネイロ', '来年ワールドカップ、2016年にはオリンピックを控えるブラジル。以前住んでいたリオデジャネイロの思い出をつらつらと書いていきます。リオは私の心のふるさとの一つです。安くて安全に楽しむための情報を発信していきますので、どうぞよろしくお願いします。', '来年ワールドカップ、2016年にはオリンピックを控えるブラジル。以前住んでいたリオデジャネイロの思い出をつらつらと書いていきます。リオは私の心のふるさとの一つです。安くて安全に楽しむための情報を発信していきますので、どうぞよろしくお願いします。', 'C', 'brazil_diary_blogger'),
(159, '日本語くらす（M君・その15）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m15.html', '2013-06-09', '日本語クラス', 'M君のクラス。忘れずに始めと終わりにお祈りをしました。今回はひらがな「ん」「へ」の練習。カルタ遊びの中で、M君の英語の発音「watermelon」が非常にきれいで驚きました。学校で英語を習っているそうです。神経衰弱は1戦のみで6対7。楽しいお勉強を主に感謝します！', 'M君のクラス。忘れずに始めと終わりにお祈りをしました。今回はひらがな「ん」「へ」の練習。カルタ遊びの中で、M君の英語の発音「watermelon」が非常にきれいで驚きました。学校で英語を習っているそうです。神経衰弱は1戦のみで6対7。楽しいお勉強を主に感謝します！', 'C', 'brazil_diary_blogger'),
(160, 'グァララペスの風景（動画その2）', 'https://tlccc-mission-bra.blogspot.com/2013/06/2.html', '2013-06-12', 'グァララペス', 'グァララペスに行って動画を撮影してきました。今回はバスターミナル（ロドヴィアリア）の風景です。動画が伝道に用いられますようにお祈りください。', 'グァララペスに行って動画を撮影してきました。今回はバスターミナル（ロドヴィアリア）の風景です。動画が伝道に用いられますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(161, 'W杯ブラジル大会情報・その1', 'https://tlccc-mission-bra.blogspot.com/2013/06/w1.html', '2013-06-13', 'サッカー', '来年のW杯ブラジル大会に向けて、コンフェデレーションズカップが行われます。ブラジル時間と日本時間は午前と午後を入れ替えればOK。日本代表とブラジルとの初戦がとても楽しみです。日本も大変強くなっています。お祈りください！', '来年のW杯ブラジル大会に向けて、コンフェデレーションズカップが行われます。ブラジル時間と日本時間は午前と午後を入れ替えればOK。日本代表とブラジルとの初戦がとても楽しみです。日本も大変強くなっています。お祈りください！', 'C', 'brazil_diary_blogger'),
(162, 'チェコからも!!', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post.html', '2013-06-15', 'ブラジル日記', 'こんにちは、エパタです。チェコからの初めてのアクセス!! ありがとうございます!! プラハからでしょうか？ (^^)', 'こんにちは、エパタです。チェコからの初めてのアクセス!! ありがとうございます!! プラハからでしょうか？ (^^)', 'C', 'brazil_diary_blogger'),
(163, 'とうとう', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_15.html', '2013-06-15', 'ブラジル日記', 'おはようございます、エパタです。ブラジル国内からのアクセスが日本からのアクセスを上回りました。ブラジルの皆さん、ありがとうございます!! (^^)', 'おはようございます、エパタです。ブラジル国内からのアクセスが日本からのアクセスを上回りました。ブラジルの皆さん、ありがとうございます!! (^^)', 'C', 'brazil_diary_blogger'),
(164, '日本語くらす（M君・その16）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m16.html', '2013-06-16', '日本語クラス', 'M君の日本語クラス。今回はひらがな「ひ」「ら」を練習し、「You are my God」の英語の歌詞を少しずつポルトガル語に翻訳して説明しました。「When I was down」の悲しい気持ちについて、お母さんに叱られた時を例にあげると「あ～、わかった！」と納得してくれました。一歩一歩進んでいます！', 'M君の日本語クラス。今回はひらがな「ひ」「ら」を練習し、「You are my God」の英語の歌詞を少しずつポルトガル語に翻訳して説明しました。「When I was down」の悲しい気持ちについて、お母さんに叱られた時を例にあげると「あ～、わかった！」と納得してくれました。一歩一歩進んでいます！', 'C', 'brazil_diary_blogger'),
(165, 'フィンランドからも !!', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_19.html', '2013-06-19', 'ブラジル日記', 'ついにフィンランドからもアクセスがありました!! ありがとうございます。この頃ヨーロッパからのアクセスが増えてきていて嬉しい。感謝いたします！', 'ついにフィンランドからもアクセスがありました!! ありがとうございます。この頃ヨーロッパからのアクセスが増えてきていて嬉しい。感謝いたします！', 'C', 'brazil_diary_blogger'),
(166, '日本語くらす（M君・その17）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m17.html', '2013-06-23', '日本語クラス', 'おばあちゃん（Aさん）の腕が痛いとのことで、癒しのために最初にお祈りしました。ずいぶん楽になったと、大変喜ばれました。授業では「は」「ま」の書き方の練習と、新しく追加したカードで「お店屋さんごっこ」。「とけい」と「けいと」の文字順の違いに気づいて、二人で大笑いしました！', 'おばあちゃん（Aさん）の腕が痛いとのことで、癒しのために最初にお祈りしました。ずいぶん楽になったと、大変喜ばれました。授業では「は」「ま」の書き方の練習と、新しく追加したカードで「お店屋さんごっこ」。「とけい」と「けいと」の文字順の違いに気づいて、二人で大笑いしました！', 'C', 'brazil_diary_blogger'),
(167, '白馬キャンプに誘いました', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_6445.html', '2013-06-23', 'ブラジル日記', 'いつものご夫妻（アーリンドさんご夫妻）にお会いして、お昼をごちそうになりました。同性婚やデモについての話をしながら、「7月23日の白馬キャンプへ一緒に行きませんか？」とお誘いしました。ご夫妻も以前から日本のために祈っておられたそうです。主が必要を満たしてくださいますように！', 'いつものご夫妻（アーリンドさんご夫妻）にお会いして、お昼をごちそうになりました。同性婚やデモについての話をしながら、「7月23日の白馬キャンプへ一緒に行きませんか？」とお誘いしました。ご夫妻も以前から日本のために祈っておられたそうです。主が必要を満たしてくださいますように！', 'C', 'brazil_diary_blogger'),
(168, 'W杯ブラジル大会情報・その2', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_24.html', '2013-06-24', 'サッカー', 'コンフェデ杯の試合をインターネットで生中継を見ながら応援しています。サッカーのポルトガル語の実況は、単語がかなり専門的でスピードも速いですが、リスニングのとても良い訓練になりますよ！がんばれ日本代表！', 'コンフェデ杯の試合をインターネットで生中継を見ながら応援しています。サッカーのポルトガル語の実況は、単語がかなり専門的でスピードも速いですが、リスニングのとても良い訓練になりますよ！がんばれ日本代表！', 'C', 'brazil_diary_blogger'),
(169, 'なぜか⁈ 直った(^^)', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post.html', '2013-07-01', 'ブラジル日記', 'サッカーブラジル代表コンフェデ杯優勝おめでとうございます！さて、調子の悪かった中国製の携帯電話をしばらく放置していたら、なぜかWi-Fi経由のブラウザが再び使えるようになりました！「色々やってダメなら、放置する。そのうち解決する」というブラジル式解決に感謝します！', 'サッカーブラジル代表コンフェデ杯優勝おめでとうございます！さて、調子の悪かった中国製の携帯電話をしばらく放置していたら、なぜかWi-Fi経由のブラウザが再び使えるようになりました！「色々やってダメなら、放置する。そのうち解決する」というブラジル式解決に感謝します！', 'C', 'brazil_diary_blogger'),
(170, '日本語くらす（M君・その18）', 'https://tlccc-mission-bra.blogspot.com/2013/07/m18.html', '2013-07-07', '日本語クラス', 'M君に日本語を教えに行きました。今回はひらがなの「よ」と「も」の書き方の練習をしました。その後、14セットのカードで神経衰弱をやり、M君の圧倒的な記憶力により大敗してしまいました。すごい記憶力です。', 'M君に日本語を教えに行きました。今回はひらがなの「よ」と「も」の書き方の練習をしました。その後、14セットのカードで神経衰弱をやり、M君の圧倒的な記憶力により大敗してしまいました。すごい記憶力です。', 'C', 'brazil_diary_blogger'),
(171, 'ポルトガル語の訂正がありました', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_7.html', '2013-07-07', '宣伝・広告', '先日書きました「白馬キャンプに誘いました」の記事のポルトガル語に間違いがあり、ブログを読んでくださっているブラジル人の方が訂正をメールにて教えてくださいました。心より感謝いたします。訂正文を赤文字で記しました。', '先日書きました「白馬キャンプに誘いました」の記事のポルトガル語に間違いがあり、ブログを読んでくださっているブラジル人の方が訂正をメールにて教えてくださいました。心より感謝いたします。訂正文を赤文字で記しました。', 'C', 'brazil_diary_blogger'),
(172, 'לברזיל', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_10.html', '2013-07-10', 'イスラエル', 'אני יפנית ואני גרה בברזיל. אני רוצה לספר איך ישוע הוביל אותי לכאן. אלוהים הוא חי. הוא מקשיב לתפילות שלנו מדבר אלינו. ואני קיבלתי את ישוע.', 'אני יפנית ואני גרה בברזיל. אני רוצה לספר איך ישוע הוביל אותי לכאן. אלוהים הוא חי. הוא מקשיב לתפילות שלנו מדבר אלינו. ואני קיבלתי את ישוע.', 'C', 'brazil_diary_blogger'),
(173, 'O meu encontro com Jesus (with English translation)', 'https://tlccc-mission-bra.blogspot.com/2013/07/o-meu-encontro-com-jesus.html', '2013-07-10', '証し', 'どのようにイエス・キリストを信じるようになったか、そしてブラジルへの召命と宣教師としての導きの証しです。主は語られたことを必ず成し遂げてくださるお方です。すべての栄光を主に！', 'どのようにイエス・キリストを信じるようになったか、そしてブラジルへの召命と宣教師としての導きの証しです。主は語られたことを必ず成し遂げてくださるお方です。すべての栄光を主に！', 'C', 'brazil_diary_blogger'),
(174, '偵察', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_16.html', '2013-07-16', '宣教活動', '「足で踏む所は与える」との約束に基づき、み声新聞を持って新しく開拓する地域へ。スーパーで出会った日系人の男性にみ声新聞とミッション誌を差し上げ、福音を語ると「はい、信じます」と言ってくださいました。主の働きに感謝します！', '「足で踏む所は与える」との約束に基づき、み声新聞を持って新しく開拓する地域へ。スーパーで出会った日系人の男性にみ声新聞とミッション誌を差し上げ、福音を語ると「はい、信じます」と言ってくださいました。主の働きに感謝します！', 'C', 'brazil_diary_blogger'),
(175, '癒しのために祈ってきました', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_22.html', '2013-07-22', '祈り', '近所に住む日系人のOさんの家の前を通ったときに、ちょうどOさんがおられました。娘さんのために癒されるよう、お祈りをしてくることができました。主がOさんに触れ続けてくださいますように。', '近所に住む日系人のOさんの家の前を通ったときに、ちょうどOさんがおられました。娘さんのために癒されるよう、お祈りをしてくることができました。主がOさんに触れ続けてくださいますように。', 'C', 'brazil_diary_blogger'),
(176, '「雲の間にある虹8月号」が届きました', 'https://tlccc-mission-bra.blogspot.com/2013/07/8.html', '2013-07-23', '宣伝・広告', '私が原稿を書かせていただいた「雲の間にある虹8月号」が届きました。また、原稿を書くために題材にさせていただいたアルファさんにポルトガル語訳をお送りし、贈呈用の見本を郵送しました。感謝します。', '私が原稿を書かせていただいた「雲の間にある虹8月号」が届きました。また、原稿を書くために題材にさせていただいたアルファさんにポルトガル語訳をお送りし、贈呈用の見本を郵送しました。感謝します。', 'C', 'brazil_diary_blogger'),
(177, 'コレ、いい〜', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_26.html', '2013-07-26', '聖書', '毎日聖書を読んでいますが、目が疲れるので聴く聖書アプリを探しました。英語ですが、ヒアリングの訓練にもなり、非常に気に入っています。', '毎日聖書を読んでいますが、目が疲れるので聴く聖書アプリを探しました。英語ですが、ヒアリングの訓練にもなり、非常に気に入っています。', 'C', 'brazil_diary_blogger'),
(178, 'コレ、いい〜 (追記)', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_890.html', '2013-07-26', '聖書', '日本語の聖書朗読アプリ「日本語聖書」も見つけました！さらにヘブライ語の新約聖書朗読アプリ「Bible Is」も発見。ほぼイエス様が話されたアラム語・ヘブライ語の音で聞けるのでツボにはまっています。おすすめです！', '日本語の聖書朗読アプリ「日本語聖書」も見つけました！さらにヘブライ語の新約聖書朗読アプリ「Bible Is」も発見。ほぼイエス様が話されたアラム語・ヘブライ語の音で聞けるのでツボにはまっています。おすすめです！', 'C', 'brazil_diary_blogger'),
(179, 'コレ、いい～（追記の追記）', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_28.html', '2013-07-28', '聖書', '日本語、英語、中国語の聖書朗読アプリの比較レビューです。やはり英語バージョンでは、中国製の「英語聖經」が、最も音声や聞き心地が気に入っています。色々なアプリを試すのが本当に楽しいです。', '日本語、英語、中国語の聖書朗読アプリの比較レビューです。やはり英語バージョンでは、中国製の「英語聖經」が、最も音声や聞き心地が気に入っています。色々なアプリを試すのが本当に楽しいです。', 'C', 'brazil_diary_blogger'),
(180, 'ファビコン？', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_29.html', '2013-07-29', 'ブラジル日記', 'ブログに小さなアイコン「ファビコン」を追加しようとHTMLとCSSコードと格闘中です。うまく設定できますようにお祈りください。', 'ブログに小さなアイコン「ファビコン」を追加しようとHTMLとCSSコードと格闘中です。うまく設定できますようにお祈りください。', 'C', 'brazil_diary_blogger'),
(181, 'できた！', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_4557.html', '2013-07-29', '動画', 'BloggerブログにHTMLのlink要素を追加して、ファビコンを無事に表示させることができました！また、GIFのバナー画像まで作ってみました。デザインの工夫が本当に楽しいです。', 'BloggerブログにHTMLのlink要素を追加して、ファビコンを無事に表示させることができました！また、GIFのバナー画像まで作ってみました。デザインの工夫が本当に楽しいです。', 'C', 'brazil_diary_blogger'),
(182, 'ツィッターを追加しました', 'https://tlccc-mission-bra.blogspot.com/2013/07/blog-post_31.html', '2013-07-31', 'ブラジル日記', 'ブログのプロフィール欄に、私の個人的なツイッターへのリンクとアイコン画像を追加しました。HTMLのaタグとimgタグを使ったコードの覚書を残しておきます。', 'ブログのプロフィール欄に、私の個人的なツイッターへのリンクとアイコン画像を追加しました。HTMLのaタグとimgタグを使ったコードの覚書を残しておきます。', 'C', 'brazil_diary_blogger'),
(183, 'ブラジルの接続事情・その10', 'https://tlccc-mission-bra.blogspot.com/2013/08/10.html', '2013-08-01', 'ブラジル日記', 'ついにブラジルでもiPhone 5が出回るようになりました。16GBで2399レアルです。また、VIVO社のADSLインターネット「Speedy」が大幅に値下げされ、一ヶ月36レアルになりました。接続事情が良くなっています！', 'ついにブラジルでもiPhone 5が出回るようになりました。16GBで2399レアルです。また、VIVO社のADSLインターネット「Speedy」が大幅に値下げされ、一ヶ月36レアルになりました。接続事情が良くなっています！', 'C', 'brazil_diary_blogger'),
(184, '児童養護施設のパンフレットもリニューアル！', 'https://tlccc-mission-bra.blogspot.com/2013/08/blog-post.html', '2013-08-02', '児童養護施設', '福島県郡山市で建設予定の児童養護施設（からし種の会）の寄付パンフレットを、無事土地を購入できたとの報告を加えてリニューアルしました。大家さんから、日系協会の会長さんや会員の皆様に配ってくださるとの嬉しいご報告をいただきました。主に感謝します！', '福島県郡山市で建設予定の児童養護施設（からし種の会）の寄付パンフレットを、無事土地を購入できたとの報告を加えてリニューアルしました。大家さんから、日系協会の会長さんや会員の皆様に配ってくださるとの嬉しいご報告をいただきました。主に感謝します！', 'C', 'brazil_diary_blogger'),
(185, '日本語くらす（M君・その19）', 'https://tlccc-mission-bra.blogspot.com/2013/08/m19.html', '2013-08-08', 'ブラジル日記', '冬休みが終わり、M君の日本語クラスを再開しました。今回は動物の名前を線でつなぐアクティビティと、ひらがな「え」「お」の練習。神経衰弱はM君と白熱し、6対6の同点でした！', '冬休みが終わり、M君の日本語クラスを再開しました。今回は動物の名前を線でつなぐアクティビティと、ひらがな「え」「お」の練習。神経衰弱はM君と白熱し、6対6の同点でした！', 'C', 'brazil_diary_blogger'),
(186, 'シオン of 丘とダビデの町について（訂正）', 'https://tlccc-mission-bra.blogspot.com/2013/08/blog-post_12.html', '2013-08-12', 'イスラエル', '以前「シオンの丘とダビデの町が同じ場所だった」と書きましたが、地図をよく見直したところ、少しずれていることが分かりました。シロアムの池などは「ダビデの町」にあり、現在のシオンの丘とは近いですが同一ではありませんでした。訂正いたします。', '以前「シオンの丘とダビデの町が同じ場所だった」と書きましたが、地図をよく見直したところ、少しずれていることが分かりました。シロアムの池などは「ダビデの町」にあり、現在のシオンの丘とは近いですが同一ではありませんでした。訂正いたします。', 'C', 'brazil_diary_blogger'),
(187, '日本語くらす（M君・その20）', 'https://tlccc-mission-bra.blogspot.com/2013/08/m20.html', '2013-08-15', 'ブラジル日記', 'M君のクラス。今回は、新しく「みてください」「きいてください」など、５つの日本語の動作の言い方と、ジェスチャーを組み合わせたゲームを行いました。交代でお互いに命令し合い、大変盛り上がりました。', 'M君のクラス。今回は、新しく「みてください」「きいてください」など、５つの日本語の動作の言い方と、ジェスチャーを組み合わせたゲームを行いました。交代でお互いに命令し合い、大変盛り上がりました。', 'C', 'brazil_diary_blogger'),
(188, 'クリスチャンになった時の体験談を話しました！', 'https://tlccc-mission-bra.blogspot.com/2013/08/blog-post_16.html', '2013-08-16', '宣教活動', '大家さんにお昼に誘われ、帰り道に「どうやって教会に行くようになったの？」と聞かれました。私がイエス様を信じるにいたった証しを真剣にすることができ、とても感動しました。彼女に「み声新聞」をプレゼントしました。主の御名をあがめます！', '大家さんにお昼に誘われ、帰り道に「どうやって教会に行くようになったの？」と聞かれました。私がイエス様を信じるにいたった証しを真剣にすることができ、とても感動しました。彼女に「み声新聞」をプレゼントしました。主の御名をあがめます！', 'C', 'brazil_diary_blogger'),
(189, 'パンフレットを持って行きました', 'https://tlccc-mission-bra.blogspot.com/2013/08/10-2022.html', '2013-08-22', 'ブラジル日記', 'お世話になっている日系の定食屋さんに、新しく作成した「日本の児童養護施設設立のための寄付のお願い」のパンフレットを10部持って行きました。その後、伝道所カフェ「BooKafe」へ。夜中のお祈りの中で出来た、歴代誌から取ったヘブライ語の賛美の歌詞を載せておきます。', 'お世話になっている日系の定食屋さんに、新しく作成した「日本の児童養護施設設立のための寄付のお願い」のパンフレットを10部持って行きました。その後、伝道所カフェ「BooKafe」へ。夜中のお祈りの中で出来た、歴代誌から取ったヘブライ語の賛美の歌詞を載せておきます。', 'C', 'brazil_diary_blogger'),
(190, '日本語くらす（M君・その21）', 'https://tlccc-mission-bra.blogspot.com/2013/08/m21.html', '2013-08-29', 'ブラジル日記', 'M君のクラス。今回、いつもの「お店屋さんごっこ」の役割交代の際に、並べたカードを裏返して「何があるかを当てる」という工夫を取り入れました。これが大ヒット！M君は俄然やる気になり、素晴らしい表情で楽しんでくれました。ひらがな「ね」「み」の練習もしました。', 'M君のクラス。今回、いつもの「お店屋さんごっこ」の役割交代の際に、並べたカードを裏返して「何があるかを当てる」という工夫を取り入れました。これが大ヒット！M君は俄然やる気になり、素晴らしい表情で楽しんでくれました。ひらがな「ね」「み」の練習もしました。', 'C', 'brazil_diary_blogger'),
(191, '健康診断に行ってきました', 'https://tlccc-mission-bra.blogspot.com/2013/08/blog-post_30.html', '2013-08-30', 'ブラジル日記', '大家さんに誘われ、町のボランティアによる健康診断に行ってきました。血圧も血糖値も正常。その後の医師による病気予防のセミナーを聴き、難しいポルトガル語の医療用語に接する良い訓練となりました。', '大家さんに誘われ、町のボランティアによる健康診断に行ってきました。血圧も血糖値も正常。その後の医師による病気予防のセミナーを聴き、難しいポルトガル語の医療用語に接する良い訓練となりました。', 'C', 'brazil_diary_blogger'),
(192, '日本語くらす（M君・その22）', 'https://tlccc-mission-bra.blogspot.com/2013/09/m22.html', '2013-09-05', 'ブラジル日記', 'M君のクラス。今回も、カードを隠して当てる「お店屋さんごっこプラスアルファ」が非常に効果的で、彼の表情がパッと明るくなりました。カードの神経衰弱は10対11で私の勝ち！ひらがな「ぬ」「わ」の書き方を練習しました。', 'M君のクラス。今回も、カードを隠して当てる「お店屋さんごっこプラスアルファ」が非常に効果的で、彼の表情がパッと明るくなりました。カードの神経衰弱は10対11で私の勝ち！ひらがな「ぬ」「わ」の書き方を練習しました。', 'C', 'brazil_diary_blogger'),
(193, '牛乳2パック', 'https://tlccc-mission-bra.blogspot.com/2013/09/2.html', '2013-09-10', 'ブラジル日記', 'スーパーで買い物をし、家に帰ると買ったはずの牛乳2パックがないことに気づきました。レジに忘れてしまったようです。しかし、「すべての事について感謝しなさい」の言葉を思い出し、神様に感謝。ダメ元でスーパーに電話すると、心良く「保管してあるから取りにおいで」と。主に感謝します！', 'スーパーで買い物をし、家に帰ると買ったはずの牛乳2パックがないことに気づきました。レジに忘れてしまったようです。しかし、「すべての事について感謝しなさい」の言葉を思い出し、神様に感謝。ダメ元でスーパーに電話すると、心良く「保管してあるから取りにおいで」と。主に感謝します！', 'C', 'brazil_diary_blogger'),
(194, '日本語くらす（M君・その23）', 'https://tlccc-mission-bra.blogspot.com/2013/09/m23.html', '2013-09-12', 'ブラジル日記', 'M君のクラス。今回から、紙粘土を使って「くつ」「たまご」などの立体的なおもちゃを一緒に作りました。これを使った「隠して当てるゲーム」がM君のツボにハマり、二人で大はしゃぎしました。おばあちゃんから焼き立てのポンデケージョを頂き、彼女の膝の癒しのために祈りました。', 'M君のクラス。今回から、紙粘土を使って「くつ」「たまご」などの立体的なおもちゃを一緒に作りました。これを使った「隠して当てるゲーム」がM君のツボにハマり、二人で大はしゃぎしました。おばあちゃんから焼き立てのポンデケージョを頂き、彼女の膝の癒しのために祈りました。', 'C', 'brazil_diary_blogger'),
(195, '日本語くらす（M君・その24）', 'https://tlccc-mission-bra.blogspot.com/2013/09/m24.html', '2013-09-19', 'ブラジル日記', 'M君のクラス。今回は、自己主張が激しくて勉強どころではなくなり、結局彼の大好きな粘土遊びになりました。私が粘土やおもちゃを隠すのを、彼が当てるのではなく、終始私が当てる側になるという、振り回されっぱなしの楽しい付き合いとなりました。遊び相手として主に感謝します！', 'M君のクラス。今回は、自己主張が激しくて勉強どころではなくなり、結局彼の大好きな粘土遊びになりました。私が粘土やおもちゃを隠すのを、彼が当てるのではなく、終始私が当てる側になるという、振り回されっぱなしの楽しい付き合いとなりました。遊び相手として主に感謝します！', 'C', 'brazil_diary_blogger'),
(196, '日本語くらす（M君・その25）', 'https://tlccc-mission-bra.blogspot.com/2013/09/m25.html', '2013-09-26', 'ブラジル日記', 'M君のクラスに行くと、おじいちゃんが「日本語のレッスンをしている宣教師だ」と、来店していたお客さんに紹介してくれました。そのお客さんは日系の方で、流暢な日本語を話されました。彼に「イエス様を信じていますか？」と聞き、彼が救われますようお祈りしました。授業は粘土遊びでした。', 'M君のクラスに行くと、おじいちゃんが「日本語のレッスンをしている宣教師だ」と、来店していたお客さんに紹介してくれました。そのお客さんは日系の方で、流暢な日本語を話されました。彼に「イエス様を信じていますか？」と聞き、彼が救われますようお祈りしました。授業は粘土遊びでした。', 'C', 'brazil_diary_blogger'),
(197, '日本語くらす（M君・その26）', 'https://tlccc-mission-bra.blogspot.com/2013/10/m26.html', '2013-10-03', 'ブラジル日記', 'おばあちゃんが、手芸の飾り「ビスキュイ」をたくさんプレゼントしてくれました。魚や動物、花などの可愛い形を見ながら、日本語で「たこ」「かい」など名前の練習をしました。M君も楽しそうに音をまねていて、お遊びを交えながらゆっくり楽しく続けています。ポンデケージョの差し入れをいただきました！', 'おばあちゃんが、手芸の飾り「ビスキュイ」をたくさんプレゼントしてくれました。魚や動物、花などの可愛い形を見ながら、日本語で「たこ」「かい」など名前の練習をしました。M君も楽しそうに音をまねていて、お遊びを交えながらゆっくり楽しく続けています。ポンデケージョの差し入れをいただきました！', 'C', 'brazil_diary_blogger'),
(198, 'エルサレムの平和のために祈る集会', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post.html', '2013-10-07', 'イスラエル', '東京で開催された「エルサレムの平和のために祈る集会」に、ブラジルからインターネット生中継で出演しました。メシアニックジューのイェフダさんご夫妻も伝統的な衣装を着て参加してくださいました。日本でこのような集会があることに深く感動しておられました。神様に栄光を！', '東京で開催された「エルサレムの平和のために祈る集会」に、ブラジルからインターネット生中継で出演しました。メシアニックジューのイェフダさんご夫妻も伝統的な衣装を着て参加してくださいました。日本でこのような集会があることに深く感動しておられました。神様に栄光を！', 'C', 'brazil_diary_blogger'),
(199, 'イタリアからのアクセスがありました', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_7.html', '2013-10-07', 'ブラジル日記', 'こんにちは、エパタです。初めてイタリアからのアクセスがありました。イタリアからのご訪問ありがとうございます。(^O^)', 'こんにちは、エパタです。初めてイタリアからのアクセスがありました。イタリアからのご訪問ありがとうございます。(^O^)', 'C', 'brazil_diary_blogger'),
(200, '日本語くらす（M君・その27）', 'https://tlccc-mission-bra.blogspot.com/2013/10/m27.html', '2013-10-10', 'ブラジル日記', 'M君のクラス。彼がタブレットで「JA先生」という日本語学習アプリを見つけ出し、楽しそうにひらがなや数字を練習していました。その後、ビスキュイの飾りカードを使い、「いくつ？」と質問して数を当てる「お店屋さんごっこ」をしました。最後にお別れの握手を求めてくれて、深く感動しました！', 'M君のクラス。彼がタブレットで「JA先生」という日本語学習アプリを見つけ出し、楽しそうにひらがなや数字を練習していました。その後、ビスキュイの飾りカードを使い、「いくつ？」と質問して数を当てる「お店屋さんごっこ」をしました。最後にお別れの握手を求めてくれて、深く感動しました！', 'C', 'brazil_diary_blogger'),
(201, 'リオデジャネイロ旅情報①', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_15.html', '2013-10-15', 'リオデジャネイロ', 'リオデジャネイロの旅情報です。ホテルの値段やビーチへのアクセスを考慮し、夜でも明るくて比較的安全なカテッチ通り（Rua do Catete）の安めの宿がおすすめです。地下鉄駅が近く、夜遅く戻っても安心。マックも近くにあります。', 'リオデジャネイロの旅情報です。ホテルの値段やビーチへのアクセスを考慮し、夜でも明るくて比較的安全なカテッチ通り（Rua do Catete）の安めの宿がおすすめです。地下鉄駅が近く、夜遅く戻っても安心。マックも近くにあります。', 'C', 'brazil_diary_blogger'),
(202, 'リオデジャネイロ旅情報②', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_2508.html', '2013-10-15', 'リオデジャネイロ', 'リオデジャネイロ市とニテロイ市をグァラナバラ湾経由で結ぶ通勤フェリーについて。運賃は200円くらい。サントス・ドゥモン空港に着陸する飛行機の間近を通るなど、安くて安全に素晴らしい景観を楽しめます。乗船はプラッサ・キンズィから。', 'リオデジャネイロ市とニテロイ市をグァラナバラ湾経由で結ぶ通勤フェリーについて。運賃は200円くらい。サントス・ドゥモン空港に着陸する飛行機の間近を通るなど、安くて安全に素晴らしい景観を楽しめます。乗船はプラッサ・キンズィから。', 'C', 'brazil_diary_blogger'),
(203, 'リオデジャネイロ旅情報③', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_16.html', '2013-10-16', 'リオデジャネイロ', 'サッカー観戦のあとに地下鉄で戻っても比較的安全な「ヴィトーリア・ホテル」の紹介。一泊90レアル程度。Wi-Fiはありませんが、オーナーが親切でアットホーム。以前日本人のサッカー選手が長期滞在していたと教えてくれました。温かい人々が自慢の宿です。', 'サッカー観戦のあとに地下鉄で戻っても比較的安全な「ヴィトーリア・ホテル」の紹介。一泊90レアル程度。Wi-Fiはありませんが、オーナーが親切でアットホーム。以前日本人のサッカー選手が長期滞在していたと教えてくれました。温かい人々が自慢の宿です。', 'C', 'brazil_diary_blogger'),
(204, '日本語くらす（M君・その28）', 'https://tlccc-mission-bra.blogspot.com/2013/10/m28.html', '2013-10-17', 'ブラジル日記', 'M君のクラス。復習として、4文字のひらがな「ようふく」「ろぼっと」「ちゅーりっぷ」などの読み方のテストをしました。かなり良く覚えていました。おばあちゃんからハーブせっけんのセットをプレゼントしていただきました。とてもいい香り！感謝いたします！', 'M君のクラス。復習として、4文字のひらがな「ようふく」「ろぼっと」「ちゅーりっぷ」などの読み方のテストをしました。かなり良く覚えていました。おばあちゃんからハーブせっけんのセットをプレゼントしていただきました。とてもいい香り！感謝いたします！', 'C', 'brazil_diary_blogger'),
(205, '体験談シリーズ・心臓発作の危機からの回復', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_22.html', '2013-10-22', '証し', '2007年9月、ブラジルチームのときのお話。リオの集会場所の担当者ホザンジェラさんのお父様が心臓発作でICUに入院されました。チームの牧師らが病院で見舞い、お父様に手を置いて熱心に祈りました。すると奇跡的に跡形もなく回復し、一週間で退院されました！主は生きておられます。ハレルヤ！', '2007年9月、ブラジルチームのときのお話。リオの集会場所の担当者ホザンジェラさんのお父様が心臓発作でICUに入院されました。チームの牧師らが病院で見舞い、お父様に手を置いて熱心に祈りました。すると奇跡的に跡形もなく回復し、一週間で退院されました！主は生きておられます。ハレルヤ！', 'C', 'brazil_diary_blogger'),
(206, '体験談シリーズ・指先のタコが取れた！', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_3339.html', '2013-10-22', '祈り', '私の右手の中指に大きなタコがあり、爪も変形していました。癒しを求めて毎日お祈りしていました。ある日、大掃除のときにその指を激しく打ち付けてしまい、内出血。しかし感謝し、祈り続けると、数日後に古い皮膚がポロッと剥がれ落ち、跡形もなく完全にきれいになりました！主をあがめます！', '私の右手の中指に大きなタコがあり、爪も変形していました。癒しを求めて毎日お祈りしていました。ある日、大掃除のときにその指を激しく打ち付けてしまい、内出血。しかし感謝し、祈り続けると、数日後に古い皮膚がポロッと剥がれ落ち、跡形もなく完全にきれいになりました！主をあがめます！', 'C', 'brazil_diary_blogger'),
(207, '体験談シリーズ・グァララペス男児のアレルギーが治った', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_23.html', '2013-10-23', 'グァララペス', '2005年のクリスマスの礼拝、2歳の男の子が激しいアレルギーで全身に発疹が出て泣き叫んでいました。私は「これこそ祈る時だ」と促され、異言で彼の額に手を当てて祈り始めました。すると、わずか数分で彼の熱が引き、発疹がみるみる消えていきました！イエス様が彼を癒されました！ハレルヤ！', '2005年のクリスマスの礼拝、2歳の男の子が激しいアレルギーで全身に発疹が出て泣き叫んでいました。私は「これこそ祈る時だ」と促され、異言で彼の額に手を当てて祈り始めました。すると、わずか数分で彼の熱が引き、発疹がみるみる消えていきました！イエス様が彼を癒されました！ハレルヤ！', 'C', 'brazil_diary_blogger'),
(208, '体験談シリーズ・リオデジャネイロで女性の鼻の病気が治った', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_1768.html', '2013-10-23', 'ポルトガル語', '2007年のリオでの伝道の時、公園のベンチで鼻の病気のために検査を受け、解雇されそうだという若い女性に出会いました。私の皮膚病が癒された証しをして、イエス様を受け入れるお祈りをし、鼻に手を当てて皆で祈りました。後日、彼女の病気が消えて解雇も免れ、お礼に来たそうです。神様をほめたたえます！', '2007年のリオでの伝道の時、公園のベンチで鼻の病気のために検査を受け、解雇されそうだという若い女性に出会いました。私の皮膚病が癒された証しをして、イエス様を受け入れるお祈りをし、鼻に手を当てて皆で祈りました。後日、彼女の病気が消えて解雇も免れ、お礼に来たそうです。神様をほめたたえます！', 'C', 'brazil_diary_blogger'),
(209, '体験談シリーズ・長期宣教師になる', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_9124.html', '2013-10-23', '証し', 'イエス様を信じて、聖書から宣教師としての召命を受けました。お金もない中、ロサンゼルスチームに参加するための費用50万円が必要に。持っていた5万円を信仰をもって捧げると、人から次々と献金が与えられ、最高額の50万円を超えてロスに行くことができました。主の恵みをあがめます！', 'イエス様を信じて、聖書から宣教師としての召命を受けました。お金もない中、ロサンゼルスチームに参加するための費用50万円が必要に。持っていた5万円を信仰をもって捧げると、人から次々と献金が与えられ、最高額の50万円を超えてロスに行くことができました。主の恵みをあがめます！', 'C', 'brazil_diary_blogger'),
(210, '日本語くらす（M君・その29）', 'https://tlccc-mission-bra.blogspot.com/2013/10/m29.html', '2013-10-24', '日本語クラス', 'M君のクラス。今回、100円ショップの「MONOPOLY」おもちゃのお金を使い、金額をカルタに設定してお店屋さんごっこをしました。お札を持って買いに来るのが本物らしくてとても嬉しそう。M君は「あお」以外の色の言い方もがんばって練習しています。', 'M君のクラス。今回、100円ショップの「MONOPOLY」おもちゃのお金を使い、金額をカルタに設定してお店屋さんごっこをしました。お札を持って買いに来るのが本物らしくてとても嬉しそう。M君は「あお」以外の色の言い方もがんばって練習しています。', 'C', 'brazil_diary_blogger'),
(211, 'リアルタイムとりなし', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_29.html', '2013-10-29', '祈り', '教会からのイスラエル・ヨーロッパチームの旅の安全のために、フライトの動きをアプリでリアルタイムに追跡しながら熱心にお祈りしています。無事に到着して、神様の大きな栄光が現れますように！', '教会からのイスラエル・ヨーロッパチームの旅の安全のために、フライトの動きをアプリでリアルタイムに追跡しながら熱心にお祈りしています。無事に到着して、神様の大きな栄光が現れますように！', 'C', 'brazil_diary_blogger'),
(212, 'リアルタイムとりなし・その２', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_2468.html', '2013-10-29', '祈り', 'ルフトハンザ組が無事テルアビブに到着、オーストリア航空も無事着陸したとの嬉しい情報が。タイムリーなとりなしの祈りの力を感じています。チームのこれからの活動が祝福されますように！', 'ルフトハンザ組が無事テルアビブに到着、オーストリア航空も無事着陸したとの嬉しい情報が。タイムリーなとりなしの祈りの力を感じています。チームのこれからの活動が祝福されますように！', 'C', 'brazil_diary_blogger'),
(213, '体験談シリーズ・リオデジャネイロへの移動', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_30.html', '2013-10-30', '証し', '1998年、神様に促されて、お金もないままバスでリオデジャネイロに向かいました。最初は誰も知り合いがいませんでしたが、バスの中で日系人の旅行会社の人に出会い、素敵なホテルを割引料金で手配してもらいました。そのおかげで、後に永住権を助けてくれる方に出会えました。主の導きに感謝！', '1998年、神様に促されて、お金もないままバスでリオデジャネイロに向かいました。最初は誰も知り合いがいませんでしたが、バスの中で日系人の旅行会社の人に出会い、素敵なホテルを割引料金で手配してもらいました。そのおかげで、後に永住権を助けてくれる方に出会えました。主の導きに感謝！', 'C', 'brazil_diary_blogger'),
(214, 'アラサトゥーバ旅情報・野生の猿がいる公園', 'https://tlccc-mission-bra.blogspot.com/2013/10/blog-post_31.html', '2013-10-31', 'アラサトゥーバ', 'アラサトゥーバの旅情報。タダで入れる州立大学（UNESP）の敷地内には、野生の「マカコ・デ・プレゴ」という小型の猿がたくさん暮らしています。管理事務所で許可をもらって食べ物をあげることもでき、とても可愛くて癒されます。バスで簡単に行けます。', 'アラサトゥーバの旅情報。タダで入れる州立大学（UNESP）の敷地内には、野生の「マカコ・デ・プレゴ」という小型の猿がたくさん暮らしています。管理事務所で許可をもらって食べ物をあげることもでき、とても可愛くて癒されます。バスで簡単に行けます。', 'C', 'brazil_diary_blogger'),
(215, '日本語くらすへ新しい生徒さん？', 'https://tlccc-mission-bra.blogspot.com/2013/11/blog-post.html', '2013-11-02', '伝道カフェ☆', '伝道カフェ「BooKafe」に行って、「ここで日本語クラスをやってもいいですか？」とオーナーにお願いしたところ、快諾をいただきました。それを近くで聞いていた別のお客さんからも「やりたい！」と。来週火曜日から新しくスタートします。ハレルヤ！', '伝道カフェ「BooKafe」に行って、「ここで日本語クラスをやってもいいですか？」とオーナーにお願いしたところ、快諾をいただきました。それを近くで聞いていた別のお客さんからも「やりたい！」と。来週火曜日から新しくスタートします。ハレルヤ！', 'C', 'brazil_diary_blogger'),
(216, '体験談シリーズ・ロサンゼルスでの思い出①運転免許', 'https://tlccc-mission-bra.blogspot.com/2013/11/blog-post_3.html', '2013-11-03', 'ブラジル日記', 'ロサンゼルスに宣教師として滞在していた時のこと。周りから「免許が必要」と言われましたが日本だと30万円。ある日、DMVに付き添いで行った際に聖霊に「あなたも並びなさい」と促され、筆記試験に挑戦。合格し、実技も教えてもらってわずか13ドルで免許を取得できました。主に感謝！', 'ロサンゼルスに宣教師として滞在していた時のこと。周りから「免許が必要」と言われましたが日本だと30万円。ある日、DMVに付き添いで行った際に聖霊に「あなたも並びなさい」と促され、筆記試験に挑戦。合格し、実技も教えてもらってわずか13ドルで免許を取得できました。主に感謝！', 'C', 'brazil_diary_blogger'),
(217, '体験談シリーズ・ブラジルへ', 'https://tlccc-mission-bra.blogspot.com/2013/11/blog-post_1952.html', '2013-11-03', 'ブラジル日記', 'ロスから帰国後、「あなたをブラジルへ遣わす」と主から言われました。その後、夢に見たのと同じ女の子に教会で出会ったり、聖書から「広い地へ導く」と語られ、テレビでブラジルの地平線を見たりしました。その後、18人の短期チームの一員としてブラジルへ出発しました。主の計画をあがめます！', 'ロスから帰国後、「あなたをブラジルへ遣わす」と主から言われました。その後、夢に見たのと同じ女の子に教会で出会ったり、聖書から「広い地へ導く」と語られ、テレビでブラジルの地平線を見たりしました。その後、18人の短期チームの一員としてブラジルへ出発しました。主の計画をあがめます！', 'C', 'brazil_diary_blogger'),
(218, '体験談シリーズ・ブラジル永住権取得', 'https://tlccc-mission-bra.blogspot.com/2013/11/blog-post_452.html', '2013-11-03', '証し', 'ブラジルに居座り、ビザが切れてしまい思い悩んでいました。しかし主から「永住権を求めなさい」と言われ、祈り始めました。10日後に、以前お世話になった旅行会社のMさんが訪ねてきて、大統領の不法滞在者向け永住権特赦の法律を教えてくれました。Mさんの援助で無事に取得。主をあがめます！', 'ブラジルに居座り、ビザが切れてしまい思い悩んでいました。しかし主から「永住権を求めなさい」と言われ、祈り始めました。10日後に、以前お世話になった旅行会社のMさんが訪ねてきて、大統領の不法滞在者向け永住権特赦の法律を教えてくれました。Mさんの援助で無事に取得。主をあがめます！', 'C', 'brazil_diary_blogger'),
(219, '日本語くらす（M君・その14）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m14.html', '2013-06-02', '日本語クラス', 'M君のクラス。ひらがな「に」「の」を練習し、「You are my God」をmp3で聞きながらひらがなを目で追う練習。16セットの神経衰弱を全力でがんばり、同点に持ち込みました。熱中しすぎてお祈りを忘れてしまいました（笑）。', 'M君のクラス。ひらがな「に」「の」を練習し、「You are my God」をmp3で聞きながらひらがなを目で追う練習。16セットの神経衰弱を全力でがんばり、同点に持ち込みました。熱中しすぎてお祈りを忘れてしまいました（笑）。', 'C', 'brazil_diary_blogger'),
(220, '日本語くらす（M君・その15）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m15.html', '2013-06-09', '日本語クラス', 'M君のクラス。忘れずに始めと終わりにお祈りをしました。ひらがな「ん」「へ」の練習。M君の英語の発音「watermelon」があまりにきれいでびっくり。学校の授業で英語を習っているそうです。楽しい一時を主に感謝します！', 'M君のクラス。忘れずに始めと終わりにお祈りをしました。ひらがな「ん」「へ」の練習。M君の英語の発音「watermelon」があまりにきれいでびっくり。学校の授業で英語を習っているそうです。楽しい一時を主に感謝します！', 'C', 'brazil_diary_blogger'),
(221, 'グァララペスの風景（動画その2）', 'https://tlccc-mission-bra.blogspot.com/2013/06/2.html', '2013-06-12', 'グァララペス', 'グァララペスに行って動画を撮影。バスターミナル（ロドヴィアリア）の風景です。動画が伝道のために用いられますように！', 'グァララペスに行って動画を撮影。バスターミナル（ロドヴィアリア）の風景です。動画が伝道のために用いられますように！', 'C', 'brazil_diary_blogger'),
(222, 'W杯ブラジル大会情報・その1', 'https://tlccc-mission-bra.blogspot.com/2013/06/w1.html', '2013-06-13', 'サッカー', '来年のW杯ブラジル大会に向け、コンフェデ杯が開幕します。日本代表とブラジルとの初戦がとても楽しみです。お祈りください！', '来年のW杯ブラジル大会に向け、コンフェデ杯が開幕します。日本代表とブラジルとの初戦がとても楽しみです。お祈りください！', 'C', 'brazil_diary_blogger'),
(223, 'チェコからも!!', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post.html', '2013-06-15', 'ブラジル日記', 'チェコからの初めてのアクセス!! ありがとうございます!! プラハからでしょうか？ (^^)', 'チェコからの初めてのアクセス!! ありがとうございます!! プラハからでしょうか？ (^^)', 'C', 'brazil_diary_blogger'),
(224, 'とうとう', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_15.html', '2013-06-15', 'ブラジル日記', 'ブラジル国内からのアクセスが日本からのアクセスを上回りました。ブラジルの皆さん、ありがとうございます!! (^^)', 'ブラジル国内からのアクセスが日本からのアクセスを上回りました。ブラジルの皆さん、ありがとうございます!! (^^)', 'C', 'brazil_diary_blogger'),
(225, '日本語くらす（M君・その16）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m16.html', '2013-06-16', '日本語クラス', 'M君の日本語クラス。今回はひらがな「ひ」「ら」を練習し、「You are my God」の英語の歌詞を少しずつポルトガル語に翻訳して説明。M君は楽しそうに納得してくれました。一歩一歩進んでいます！', 'M君の日本語クラス。今回はひらがな「ひ」「ら」を練習し、「You are my God」の英語の歌詞を少しずつポルトガル語に翻訳して説明。M君は楽しそうに納得してくれました。一歩一歩進んでいます！', 'C', 'brazil_diary_blogger'),
(226, 'フィンランドからも !!', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_19.html', '2013-06-19', 'ブラジル日記', 'フィンランドからもアクセスがありました!! ありがとうございます。ヨーロッパからのアクセスが増えていて嬉しい。感謝いたします！', 'フィンランドからもアクセスがありました!! ありがとうございます。ヨーロッパからのアクセスが増えていて嬉しい。感謝いたします！', 'C', 'brazil_diary_blogger'),
(227, '日本語くらす（M君・その17）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m17.html', '2013-06-23', '日本語クラス', 'おばあちゃん（Aさん）の腕が痛いとのことで、癒しのために最初にお祈りし、大変喜ばれました。授業では「は」「ま」の書き方の練習と、新しく追加したカードで「お店屋さんごっこ」。「とけい」と「けいと」の文字順の違いに気づいて、二人で大笑いしました！', 'おばあちゃん（Aさん）の腕が痛いとのことで、癒しのために最初にお祈りし、大変喜ばれました。授業では「は」「ま」の書き方の練習と、新しく追加したカードで「お店屋さんごっこ」。「とけい」と「けいと」の文字順の違いに気づいて、二人で大笑いしました！', 'C', 'brazil_diary_blogger'),
(228, '白馬キャンプに誘いました', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_6445.html', '2013-06-23', 'ブラジル日記', 'ご夫妻にお会いして、お昼をごちそうになりました。「7月23日の白馬キャンプへ一緒に行きませんか？」とお誘いしました。ご夫妻も以前から日本のために祈っておられたそうです。主が必要を満たしてくださいますように！', 'ご夫妻にお会いして、お昼をごちそうになりました。「7月23日の白馬キャンプへ一緒に行きませんか？」とお誘いしました。ご夫妻も以前から日本のために祈っておられたそうです。主が必要を満たしてくださいますように！', 'C', 'brazil_diary_blogger'),
(229, 'W杯ブラジル大会情報・その2', 'https://tlccc-mission-bra.blogspot.com/2013/06/blog-post_24.html', '2013-06-24', 'サッカー', 'コンフェデ杯の試合をインターネットで生中継を見ながら応援。サッカーの実況は、リスニングのとても良い訓練になります！がんばれ日本代表！', 'コンフェデ杯の試合をインターネットで生中継を見ながら応援。サッカーの実況は、リスニングのとても良い訓練になります！がんばれ日本代表！', 'C', 'brazil_diary_blogger'),
(230, '母の腰の痛みがやわらいだ', 'https://tlccc-mission-bra.blogspot.com/2013/05/blog-post_31.html', '2013-05-31', '祈り', '母の腰痛のためにお祈り。痛みを感じずに過ごすことができたそうです。また、甥っ子たちの学校が合併して遠くなった件。良いお友達ができるように祈っていましたが、楽しく通えているそうです。ハレルヤ！', '母の腰痛のためにお祈り。痛みを感じずに過ごすことができたそうです。また、甥っ子たちの学校が合併して遠くなった件。良いお友達ができるように祈っていましたが、楽しく通えているそうです。ハレルヤ！', 'C', 'brazil_diary_blogger'),
(231, '日本語くらす（M君・その14）', 'https://tlccc-mission-bra.blogspot.com/2013/06/m14.html', '2013-06-02', '日本語クラス', 'ひらがな「に」「の」を練習し、「You are my God」をmp3で聞きながらひらがなを目で追う練習。神経衰弱は16セットで全力でがんばり、同点に持ち込みました。お祈りを忘れてしまいました（笑）。', 'ひらがな「に」「の」を練習し、「You are my God」をmp3で聞きながらひらがなを目で追う練習。神経衰弱は16セットで全力でがんばり、同点に持ち込みました。お祈りを忘れてしまいました（笑）。', 'C', 'brazil_diary_blogger'),
